-- Industries locale merge
-- Source: docs/LanguageAddon/Translations/Industries.csv
-- Data-only UPDATE. No ALTER TABLE. No published-flag changes.
-- Run in the Supabase SQL editor when ready. Take a backup first.
-- Merges en/it/fr/de/es into existing JSONB locale objects. Blank CSV cells are skipped.
-- Warning: the admin industries editor still saves only en/it. Saving an industry there will wipe fr/de/es until that editor is extended.

BEGIN;

-- industry_solutions 88f125a1-b731-4da7-a59d-6da23446e550
UPDATE industry_solutions
SET industry_name_locales = COALESCE(industry_name_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Glass Manufacturing"'::jsonb,
    'it', '"Produzione del Vetro"'::jsonb,
    'fr', '"Production du verre"'::jsonb,
    'de', '"Glasproduktion"'::jsonb,
    'es', '"Producción de vidrio"'::jsonb
  ),
  description_locales = COALESCE(description_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Industry-Specific PPE Solutions for Glass Manufacturing\nHand Line delivers comprehensive personal protective equipment (PPE) solutions tailored to each stage of the glass manufacturing process:\nRaw Material Handling & Batching – Controls silica dust, chemical irritation, and ergonomic strain with P3 respirators, chemical- and ergonomic gloves, and dust swabs.\nHot End & Forming – Manages extreme heat, molten spatter, cut risks, and pinch points using aluminized and composite gloves, cotton lubrication swabs, PAPRs, and heat-reflective gear.\nAnnealing & Cold End Inspection – Mitigates stress cracks, glass dust, and noise through cut-resistant PPE, particulate respirators, hearing protection, and precision swabs/brushes.\nMaintenance & Repair – Protects against electrical hazards, confined spaces, chemicals, and falls with dielectric/arc-flash PPE, harnesses, chemical gloves, respirators, and non-shedding swabs.\nPackaging, Logistics & Recycling – Addresses ergonomic lifting, crush and cut hazards, dust, and chemical residues via ergonomic impact gloves, chainmail and cut-resistant gear, safety boots, dust respirators, and quick-change swabs.\nBy offering gloves, respirators, swabs, and ancillary PPE tailored to each operational risk, Hand Line ensures regulatory compliance, minimizes downtime, and fosters a culture of safety across all production stages.\n\n1. Raw Material Handling & Batching\nOperators receive, store, and accurately weigh raw ingredients—silica sand, soda ash, limestone, and recycled cullet—often in bulk bags or silos.\nKey Hazards:\nDust Inhalation: Fine silica and other mineral dusts become airborne during transfer and weighing, posing respiratory and long-term silicosis risks.\nErgonomic Strain: Repetitive lifting of heavy sacks or manipulating bulk container fittings can lead to musculoskeletal injuries.\nChemical Exposure: Additives (e.g., sodium sulfate, cullet residues) may irritate skin or eyes upon contact.\nPPE Solutions:\nP3/HEPA Respirators or PAPR Units to filter respirable silica and dusts, mitigating inhalation hazards.\nChemical-Resistant Gloves (Nitrile/Neoprene) for handling additives that could cause skin irritation.\nErgonomic Gloves with Padded Palms to cushion and improve grip, reducing hand fatigue during repetitive movements.\nHigh-Efficiency Dust Swabs for sampling and cleaning fine dust accumulations without re-aerosolizing particles.\n\n2. Hot End & Forming Operations (Cave-Glass Bottles)\nMolten glass is melted in furnaces >1,500 °C, conditioned, and delivered to molds. Workers adjust refractories, stir melts, lubricate molds with cotton swabs; then molten glass is formed into bottles and transferred—manually or robotically—to annealing lehrs.\nKey Hazards:\nThermal Burns & Radiant Heat: Contact with furnaces, molds, or spatter causes severe burns.\nMolten Spatter: Droplets of molten glass can eject during stirring or mold filling.\nContact Heat During Lubrication: Applying release agents with cotton swabs to hot molds exposes hands to contact and radiant heat.\nCut & Abrasion Injuries: Sharp edges on freshly formed bottles or breakages.\nCrush/Pinch Points: During robotic pick-and-place or manual handling of hot bottles.\nFume Exposure: Emissions of silica, metal oxides, and combustion byproducts pose inhalation risks.\nPPE Solutions:\nHigh-Heat, High-Contact Resistant Gloves: Aluminized, Kevlar-reinforced gauntlets with insulated liners and reinforced back-of-hand protection for mold lubrication and bottle transfers.\nCut- & Heat-Resistant Composite Gloves: Combine HPPE fibers and heat-insulating liners to protect against lacerations and surface heat during handling.\nCotton Swabs for Mold Lubrication: High-temp cotton swabs designed to carry release agents, resisting degradation and minimizing hand exposure.\nPAPRs with High-Temperature Silicone Seals: Safe breathing in hot, particulate-laden atmospheres.\nHeat-Reflective Clothing & Full-Face Shields: Deflect radiant heat and guard against spatter.\nMechanical-Assist Transfer Gloves: Improve grip control on hot, slippery surfaces, reducing pinch risks.\nN95/N100 Respirators: Filter fine glass particulates from mold release agents or dust.\nLint-Free Inspection Swabs: For quality checks, ensuring no fibers contaminate the bottle surface.\n\n3. Annealing & Cold End Inspection\nBottles cool gradually in lehrs; afterwards, visual and automated inspections detect defects.\nKey Hazards:\nThermal Stress Cracks: Sharp fragments can form as glass cools unevenly.\nGlass Dust Exposure: Automated grinding or defect removal generates respirable particles.\nHigh Noise Levels: Conveyor and inspection machinery contribute to elevated dB levels.\nPPE Solutions:\nCut-Resistant Sleeves & Gloves to protect against sharp stress cracks during manual inspection.\nDust & Particulate Respirators to filter airborne glass dust from grinding and defect removal.\nHearing Protection (Earplugs/Earmuffs) to attenuate noise above safe thresholds.\nInspection Swabs & Brushes for precise removal of chips without spreading debris.\n\n4. Maintenance & Repair Maintenance & Repair. Maintenance & Repair\nPlanned or emergency work on furnaces, lehrs, conveyors, and electrical systems.\nKey Hazards:\nConfined Space Entry: Oxygen deficiency or toxic atmospheres in furnace cavities.\nElectrical Shock & Arc Flash: Live-line work on high-voltage components.\nChemical Contact: Cleaning solvents and refractory binders.\nHeight & Fall Risks: Servicing elevated sections of equipment.\nPPE Solutions:\nDielectric Electrical Gloves (Class 2/3) for energized work up to specified kV.\nArc-Flash Rated Suits & Face Shields to guard against flash burns and projectiles.\nFull-Body Harnesses & Lanyards for fall arrest during elevated maintenance.\nChemical-Resistant Gloves & Respirators for solvent handling and fume protection.\nNon-Shedding Industrial Swabs for cleaning electrical contacts to maintain conductivity.\n\n5. Packaging, Logistics & Recycling\nAfter inspection, bottles are packed into cartons or crates, palletized, and either shipped or sent for recycling processing. Waste streams (cullet, rejects, slag) are collected, screened, and prepared for reuse.\nKey Hazards:\nErgonomic Strain: Manual lifting of cases, pallets, and waste containers can cause musculoskeletal injuries.\nCrush & Drop Hazards: Bottles, cases, pallets, or heavy cullet may fall, risking foot and limb injuries.\nSharp Shards & Abrasions: Broken bottles and slag fragments pose cut risks.\nDust & Silica Exposure: Handling cullet and rejects generates fine particulates.\nChemical Residues: Waste glass may carry residues from prior processing.\nPPE Solutions:\nErgonomic Impact-Reducing Gloves: Padded gloves to reduce vibration and fatigue during lifting and packing.\nCut-Resistant Sleeves & Chainmail Gloves: Combined solutions for forearms and hands to guard against shards.\nMetatarsal & Steel-Toe Safety Boots: Protect feet from dropped objects and chemical exposure.\nP3/HEPA Dust Respirators & Safety Glasses: Filter fine dust while shielding eyes from debris.\nQuick-Change Dust & Contamination Swabs: For swift residue sampling and cleanup without re-aerosolizing particles."'::jsonb,
    'it', '"Soluzioni DPI Specifiche per l’Industria della Vetreria\nHand Line offre soluzioni complete di dispositivi di protezione individuale (DPI) su misura per ciascuna fase del processo di produzione del vetro:\nGestione e Dosaggio delle Materie Prime\nControllo delle polveri di silice, irritazioni chimiche e stress ergonomico con respiratori P3, guanti chimici ed ergonomici e tamponi antipolvere.\nForno e Operazioni di Formatura\nGestione di calore estremo, schizzi di vetro fuso, rischio di tagli e schiacciamenti con guanti aluminizzati e compositi, tamponi di cotone per lubrificazione, unità PAPR e abbigliamento riflettente.\nRicottura e Controllo a Freddo\nMitigazione di crepe da stress termico, polveri di vetro e rumore tramite DPI resistenti ai tagli, respiratori per particolato, protezioni acustiche e tamponi/spazzole di precisione.\nManutenzione e Riparazioni\nProtezione da rischi elettrici, spazi confinati, sostanze chimiche e cadute con guanti isolanti/arc-flash, imbracature, guanti chimici, respiratori e tamponi non contaminanti.\nImballaggio, Logistica e Riciclaggio\nGestione di sollevamenti ergonomici, rischi di schiacciamento e tagli, polveri e residui chimici con guanti antiurto ergonomici, guanti in maglia metallica e resistenti ai tagli, scarpe antinfortunistiche, respiratori P3 e tamponi rapidi.\nOffrendo guanti, respiratori, tamponi e altri DPI calibrati sui rischi operativi, Hand Line garantisce conformità normativa, riduce i rischi di fermo impianto e promuove una cultura della sicurezza in tutte le fasi produttive.\n\n1. Gestione e Dosaggio delle Materie Prime\nGli operatori ricevono, stoccano e pesano con precisione gli ingredienti grezzi — sabbia silice, soda, calcare e vetro riciclato (cullet) — spesso in sacchi sfusi o silos.\n\n\nPrincipali Rischi:\nInalazione di polveri: Le polveri fini diventano aerodisperse durante trasferimento e pesatura, con rischio respiratorio e di silicosi.\nSforzi ergonomici: Sollevamento ripetuto di sacchi pesanti e manipolazione di contenitori sfusi può causare lesioni muscoloscheletriche.\nEsposizione chimica: Additivi (es. solfato di sodio, residui di cullet) possono irritare pelle e occhi.\nSoluzioni DPI:\nRespiratori P3/HEPA o unità PAPR per filtrare silice e polveri respirabili.\nGuanti chimico-resistenti (nitrile/neoprene).\nGuanti ergonomici con palmo imbottito.\nTamponi antipolvere ad alta efficienza per campionamento e pulizia.\n\n2. Forno e Operazioni di Formatura (Vasi in Vetro)\nIl vetro fuso (>1.500 °C) viene condizionato e trasferito negli stampi. Gli operatori regolano i refrattari, mescolano il bagno, lubrificano gli stampi con tamponi di cotone, poi formano le bottiglie e le trasferiscono — manualmente o roboticamente — ai forni di ricottura.\n\n\nPrincipali Rischi:\nUstioni termiche e calore radiante\nSchizzi di vetro fuso\nCalore da contatto durante la lubrificazione\nTagli e abrasioni da bordi affilati\nSchiacciamenti e punti di presa\nEsposizione a fumi (silice, ossidi metallici)\n\n\nSoluzioni DPI:\nGuanti aluminizzati rinforzati in Kevlar con fodera isolante\nGuanti compositi resistenti a tagli e calore\nTamponi di cotone ad alta temperatura\nPAPRs con guarnizioni in silicone ad alta temperatura\nIndumenti riflettenti e visiere integrali\nGuanti meccanici assistiti\nRespiratori N95/N100\nTamponi ispezione senza lanugine\n\n3. Ricottura e Controllo a Freddo\nLe bottiglie si raffreddano nei forni di ricottura; quindi si effettuano ispezioni visive e automatizzate per rilevare difetti.\n\n\nPrincipali Rischi:\nCrepe da stress termico\nEsposizione a polveri di vetro durante molatura o rimozione difetti\nRumore elevato da nastri e macchinari\n\n\nSoluzioni DPI:\nManiche e guanti resistenti ai tagli\nRespiratori per polveri e particolato\nProtezioni auricolari (tappi o cuffie)\nTamponi e spazzole di ispezione\n\n4. Manutenzione e Riparazioni\nInterventi programmati o di emergenza su forni, ricottatori, nastri e impianti elettrici.\nLa sostituzione degli stampi e il cambio della produzione rappresentano fasi critiche per il processo.\n\n\nPrincipali Rischi:\nSpazi confinati (carenza di ossigeno, atmosfere tossiche)\nScosse elettriche e arc-flash\nContatto con solventi e leganti refrattari\nLavori in quota\nSoluzioni DPI:\nGuanti isolanti elettrici (Classe 2/3)\nTute e visiere arc-flash\nImbracature anticaduta\nGuanti chimico-resistenti e respiratori\nScovoli non contaminanti per contatti elettrici\n\n5. Imballaggio, Logistica e Riciclo\nDopo l’ispezione, le bottiglie vengono confezionate, palletizzate e spedite o avviate al riciclo; gli scarti (cullet, scarti, scorie) vengono raccolti e preparati per il riuso.\n\n\nPrincipali Rischi:\nSforzi ergonomici nel sollevamento\nRischi di schiacciamento e caduta di oggetti\nSchegge e abrasioni da frammenti di vetro\nPolveri e silice da materiale di scarto\nEsposizione a residui chimici\n\n\nSoluzioni DPI:\nGuanti ergonomici antiurto\nManiche resistenti ai tagli e guanti in maglia metallica\nScarpe antinfortunistiche con puntale e protezione metatarsale\nRespiratori P3/HEPA e occhiali di sicurezza\nScovoli rapidi per campionamento e pulizia"'::jsonb,
    'fr', '"Solutions EPI spécifiques pour l’industrie du verre\nHand Line propose des solutions complètes d’équipements de protection individuelle (EPI) sur mesure pour chaque étape du processus de production du verre :\nGestion et dosage des matières premières\nContrôle des poussières de silice, des irritations chimiques et du stress ergonomique avec des respirateurs P3, des gants chimiques et ergonomiques et des tampons anti-poussière.\nFour et opérations de formage\nGestion de la chaleur extrême, des projections de verre en fusion, des risques de coupure et d’écrasement avec des gants aluminisés et composites, des tampons en coton pour la lubrification, des unités PAPR et des vêtements réfléchissants.\nRecuisson et contrôle à froid\nAtténuation des fissures dues au stress thermique, des poussières de verre et du bruit avec des EPI résistants à la coupure, des respirateurs à particules, des protections auditives et des tampons/brosses de précision.\nMaintenance et réparations\nProtection contre les risques électriques, les espaces confinés, les produits chimiques et les chutes, avec des gants isolants/anti-arc, des harnais, des gants chimiques, des respirateurs et des tampons non contaminants.\nEmballage, logistique et recyclage\nGestion des levages ergonomiques, des risques d’écrasement et de coupure, des poussières et des résidus chimiques avec des gants ergonomiques anti-choc, des gants en maille métallique et résistants à la coupure, des chaussures de sécurité, des respirateurs P3 et des tampons rapides.\nEn proposant gants, respirateurs, tampons et autres EPI calibrés selon les risques opérationnels, Hand Line garantit la conformité réglementaire, réduit les risques d’arrêt de production et favorise une culture de la sécurité à toutes les étapes.\n\n1. Gestion et dosage des matières premières\nLes opérateurs reçoivent, stockent et pèsent avec précision les matières premières — sable siliceux, soude, calcaire et calcin (verre recyclé) — souvent en sacs en vrac ou en silos.\n\n\nPrincipaux risques :\nInhalation de poussières : Les poussières fines deviennent aéroportées lors du transfert et de la pesée, avec un risque respiratoire et de silicose.\nEfforts ergonomiques : Le levage répété de sacs lourds et la manipulation de conteneurs en vrac peuvent provoquer des lésions musculo-squelettiques.\nExposition chimique : Les additifs (par ex. sulfate de sodium, résidus de calcin) peuvent irriter la peau et les yeux.\nSolutions EPI :\nRespirateurs P3/HEPA ou unités PAPR pour filtrer la silice et les poussières respirables.\nGants résistants aux produits chimiques (nitrile/néoprène).\nGants ergonomiques avec paume rembourrée.\nTampons anti-poussière à haute efficacité pour l’échantillonnage et le nettoyage.\n\n2. Four et opérations de formage (récipients en verre)\nLe verre en fusion (>1.500 °C) est conditionné puis transféré dans les moules. Les opérateurs ajustent les réfractaires, mélangent le bain, lubrifient les moules avec des tampons en coton, puis forment les bouteilles et les transfèrent — manuellement ou par robot — vers les fours de recuisson.\n\n\nPrincipaux risques :\nBrûlures thermiques et chaleur radiante\nProjections de verre en fusion\nChaleur de contact pendant la lubrification\nCoupures et abrasions dues aux bords tranchants\nÉcrasements et points de pincement\nExposition aux fumées (silice, oxydes métalliques)\n\n\nSolutions EPI :\nGants aluminisés renforcés en Kevlar avec doublure isolante\nGants composites résistants à la coupure et à la chaleur\nTampons en coton résistants aux hautes températures\nPAPR avec joints en silicone résistants aux hautes températures\nVêtements réfléchissants et visières intégrales\nGants d’assistance mécanique\nRespirateurs N95/N100\nTampons d’inspection non pelucheux\n\n3. Recuisson et contrôle à froid\nLes bouteilles refroidissent dans les fours de recuisson ; des inspections visuelles et automatisées détectent ensuite les défauts.\n\n\nPrincipaux risques :\nFissures dues au stress thermique\nExposition aux poussières de verre pendant le meulage ou l’élimination des défauts\nBruit élevé provenant des convoyeurs et des machines\n\n\nSolutions EPI :\nManchettes et gants résistants à la coupure\nRespirateurs contre les poussières et les particules\nProtections auditives (bouchons ou casques antibruit)\nTampons et brosses d’inspection\n\n4. Maintenance et réparations\nInterventions programmées ou d’urgence sur fours, arches de recuisson, convoyeurs et installations électriques.\nLe remplacement des moules et le changement de production constituent des étapes critiques du processus.\n\n\nPrincipaux risques :\nEspaces confinés (manque d’oxygène, atmosphères toxiques)\nChocs électriques et arc électrique\nContact avec des solvants et des liants réfractaires\nTravaux en hauteur\nSolutions EPI :\nGants isolants électriques (Classe 2/3)\nCombinaisons et visières anti-arc électrique\nHarnais antichute\nGants résistants aux produits chimiques et respirateurs\nÉcouvillons non contaminants pour les contacts électriques\n\n5. Emballage, logistique et recyclage\nAprès inspection, les bouteilles sont conditionnées, palettisées et expédiées ou envoyées au recyclage ; les déchets (calcin, rebuts, scories) sont collectés et préparés pour réutilisation.\n\n\nPrincipaux risques :\nEfforts ergonomiques liés au levage\nRisques d’écrasement et de chute d’objets\nÉclats et abrasions dus aux fragments de verre\nPoussières et silice provenant des déchets\nExposition aux résidus chimiques\n\n\nSolutions EPI :\nGants ergonomiques anti-choc\nManchettes résistantes à la coupure et gants en maille métallique\nChaussures de sécurité avec embout et protection métatarsienne\nRespirateurs P3/HEPA et lunettes de sécurité\nÉcouvillons rapides pour l’échantillonnage et le nettoyage"'::jsonb,
    'de', '"Spezifische PSA-Lösungen für die Glasindustrie\nHand Line bietet umfassende, maßgeschneiderte Lösungen für persönliche Schutzausrüstung (PSA) für jede Phase des Glasherstellungsprozesses:\nHandhabung und Dosierung der Rohstoffe\nKontrolle von Quarzstaub, chemischen Reizungen und ergonomischer Belastung mit P3-Atemschutzmasken, Chemikalien- und Ergonomiehandschuhen sowie Staubschutztüchern.\nOfen und Formgebungsvorgänge\nBeherrschung von extremer Hitze, Spritzern von geschmolzenem Glas, Schnitt- und Quetschgefahren mit aluminisierten und Verbundhandschuhen, Baumwolltüchern zum Schmieren, PAPR-Einheiten und reflektierender Kleidung.\nKühlen (Tempern) und Kaltkontrolle\nMinderung von Rissen durch thermische Belastung, Glasstaub und Lärm mittels schnittfester PSA, Partikelatemschutzmasken, Gehörschutz und Präzisionstüchern/-bürsten.\nWartung und Reparaturen\nSchutz vor elektrischen Gefahren, engen Räumen, Chemikalien und Stürzen mit isolierenden/Lichtbogen-Handschuhen, Sicherheitsgurten, Chemikalienschutzhandschuhen, Atemschutzmasken und kontaminationsfreien Tüchern.\nVerpackung, Logistik und Recycling\nBewältigung von ergonomischem Heben, Quetsch- und Schnittgefahren, Staub und chemischen Rückständen mit ergonomischen Stoßschutzhandschuhen, Kettenhandschuhen und schnittfesten Handschuhen, Sicherheitsschuhen, P3-Atemschutzmasken und Schnelltüchern.\nDurch das Angebot von Handschuhen, Atemschutzmasken, Tüchern und anderer PSA, die auf die betrieblichen Risiken abgestimmt sind, gewährleistet Hand Line die Einhaltung gesetzlicher Vorschriften, verringert das Risiko von Anlagenstillständen und fördert eine Sicherheitskultur in allen Produktionsphasen.\n\n1. Handhabung und Dosierung der Rohstoffe\nDie Bediener nehmen die Rohstoffe – Quarzsand, Soda, Kalkstein und Recyclingglas (Scherben) – entgegen, lagern sie und wiegen sie präzise ab, häufig aus Schüttgutsäcken oder Silos.\n\n\nHauptrisiken:\nStaubinhalation: Feinstaub wird beim Transfer und Wiegen luftgetragen, mit Atemwegsrisiko und Silikosegefahr.\nErgonomische Belastungen: Wiederholtes Heben schwerer Säcke und die Handhabung von Schüttgutbehältern können zu Muskel-Skelett-Verletzungen führen.\nChemische Exposition: Zusatzstoffe (z. B. Natriumsulfat, Scherbenrückstände) können Haut und Augen reizen.\nPSA-Lösungen:\nP3-/HEPA-Atemschutzmasken oder PAPR-Einheiten zur Filterung von Quarz- und einatembarem Staub.\nChemikalienbeständige Handschuhe (Nitril/Neopren).\nErgonomische Handschuhe mit gepolsterter Handfläche.\nHocheffiziente Staubschutztücher für Probenahme und Reinigung.\n\n2. Ofen und Formgebungsvorgänge (Glasbehälter)\nDas geschmolzene Glas (>1.500 °C) wird konditioniert und in die Formen überführt. Die Bediener stellen die feuerfesten Materialien ein, rühren das Bad um, schmieren die Formen mit Baumwolltüchern und formen anschließend die Flaschen, die manuell oder robotergestützt zu den Kühlöfen transportiert werden.\n\n\nHauptrisiken:\nThermische Verbrennungen und Strahlungswärme\nSpritzer von geschmolzenem Glas\nKontaktwärme beim Schmieren\nSchnitte und Abschürfungen durch scharfe Kanten\nQuetschungen und Fangstellen\nRauchexposition (Quarz, Metalloxide)\n\n\nPSA-Lösungen:\nAluminisierte, Kevlar-verstärkte Handschuhe mit isolierendem Innenfutter\nVerbundhandschuhe, schnitt- und hitzebeständig\nHochtemperaturbeständige Baumwolltücher\nPAPR-Systeme mit hochtemperaturbeständigen Silikondichtungen\nReflektierende Kleidung und Vollsichtvisiere\nMechanisch unterstützte Handschuhe\nN95/N100-Atemschutzmasken\nFusselfreie Inspektionstücher\n\n3. Kühlen (Tempern) und Kaltkontrolle\nDie Flaschen kühlen in den Kühlöfen ab; anschließend werden visuelle und automatisierte Inspektionen zur Fehlererkennung durchgeführt.\n\n\nHauptrisiken:\nRisse durch thermische Belastung\nStaubexposition durch Glasstaub beim Schleifen oder bei der Fehlerbeseitigung\nHoher Lärmpegel durch Förderbänder und Maschinen\n\n\nPSA-Lösungen:\nSchnittfeste Armschützer und Handschuhe\nAtemschutzmasken gegen Staub und Partikel\nGehörschutz (Gehörschutzstöpsel oder Kapselgehörschutz)\nInspektionstücher und -bürsten\n\n4. Wartung und Reparaturen\nGeplante oder Notfalleinsätze an Öfen, Kühlöfen, Förderbändern und elektrischen Anlagen.\nDer Formenwechsel und der Produktionswechsel stellen kritische Phasen des Prozesses dar.\n\n\nHauptrisiken:\nEnge Räume (Sauerstoffmangel, toxische Atmosphären)\nStromschläge und Lichtbögen\nKontakt mit Lösungsmitteln und feuerfesten Bindemitteln\nArbeiten in der Höhe\nPSA-Lösungen:\nElektrisch isolierende Handschuhe (Klasse 2/3)\nLichtbogenschutzanzüge und -visiere\nAbsturzsicherungsgurte\nChemikalienbeständige Handschuhe und Atemschutzmasken\nKontaminationsfreie Reinigungsstäbchen für elektrische Kontakte\n\n5. Verpackung, Logistik und Recycling\nNach der Inspektion werden die Flaschen verpackt, palettiert und versandt oder dem Recycling zugeführt; Abfälle (Scherben, Ausschuss, Schlacke) werden gesammelt und für die Wiederverwendung aufbereitet.\n\n\nHauptrisiken:\nErgonomische Belastungen beim Heben\nQuetschgefahren und herabfallende Gegenstände\nSplitter und Abschürfungen durch Glasscherben\nStaub und Quarz aus Abfallmaterial\nExposition gegenüber chemischen Rückständen\n\n\nPSA-Lösungen:\nErgonomische Stoßschutzhandschuhe\nSchnittfeste Armschützer und Kettenhandschuhe\nSicherheitsschuhe mit Zehenschutzkappe und Mittelfußschutz\nP3-/HEPA-Atemschutzmasken und Schutzbrillen\nSchnellreinigungsstäbchen für Probenahme und Reinigung"'::jsonb,
    'es', '"Soluciones de EPI específicas para la industria del vidrio\nHand Line ofrece soluciones completas de equipos de protección individual (EPI) a medida para cada fase del proceso de producción del vidrio:\nGestión y dosificación de materias primas\nControl del polvo de sílice, las irritaciones químicas y el estrés ergonómico con respiradores P3, guantes químicos y ergonómicos, y paños antipolvo.\nHorno y operaciones de conformado\nGestión del calor extremo, las salpicaduras de vidrio fundido y el riesgo de cortes y aplastamientos con guantes aluminizados y compuestos, paños de algodón para lubricación, unidades PAPR y ropa reflectante.\nRecocido y control en frío\nMitigación de grietas por estrés térmico, polvo de vidrio y ruido mediante EPI resistentes al corte, respiradores para partículas, protección auditiva y paños/cepillos de precisión.\nMantenimiento y reparaciones\nProtección contra riesgos eléctricos, espacios confinados, sustancias químicas y caídas con guantes aislantes/antiarco eléctrico, arneses, guantes químicos, respiradores y paños no contaminantes.\nEmbalaje, logística y reciclaje\nGestión de la elevación ergonómica, los riesgos de aplastamiento y corte, el polvo y los residuos químicos con guantes ergonómicos antiimpacto, guantes de malla metálica y resistentes al corte, calzado de seguridad, respiradores P3 y paños rápidos.\nAl ofrecer guantes, respiradores, paños y otros EPI calibrados según los riesgos operativos, Hand Line garantiza el cumplimiento normativo, reduce los riesgos de parada de planta y promueve una cultura de seguridad en todas las fases de producción.\n\n1. Gestión y dosificación de materias primas\nLos operarios reciben, almacenan y pesan con precisión las materias primas —arena de sílice, sosa, caliza y vidrio reciclado (calcín)— a menudo en sacos a granel o silos.\n\n\nPrincipales riesgos:\nInhalación de polvo: El polvo fino se dispersa en el aire durante el traslado y el pesaje, con riesgo respiratorio y de silicosis.\nEsfuerzos ergonómicos: El levantamiento repetido de sacos pesados y la manipulación de contenedores a granel pueden causar lesiones musculoesqueléticas.\nExposición química: Los aditivos (por ejemplo, sulfato de sodio, residuos de calcín) pueden irritar la piel y los ojos.\nSoluciones de EPI:\nRespiradores P3/HEPA o unidades PAPR para filtrar sílice y polvo respirable.\nGuantes resistentes a productos químicos (nitrilo/neopreno).\nGuantes ergonómicos con palma acolchada.\nPaños antipolvo de alta eficiencia para muestreo y limpieza.\n\n2. Horno y operaciones de conformado (envases de vidrio)\nEl vidrio fundido (>1.500 °C) se acondiciona y se transfiere a los moldes. Los operarios ajustan los materiales refractarios, mezclan el baño, lubrican los moldes con paños de algodón y luego forman las botellas y las transfieren —manual o robóticamente— a los hornos de recocido.\n\n\nPrincipales riesgos:\nQuemaduras térmicas y calor radiante\nSalpicaduras de vidrio fundido\nCalor por contacto durante la lubricación\nCortes y abrasiones por bordes afilados\nAplastamientos y puntos de atrapamiento\nExposición a humos (sílice, óxidos metálicos)\n\n\nSoluciones de EPI:\nGuantes aluminizados reforzados con Kevlar y forro aislante\nGuantes compuestos resistentes al corte y al calor\nPaños de algodón resistentes a altas temperaturas\nPAPR con juntas de silicona resistentes a altas temperaturas\nRopa reflectante y viseras integrales\nGuantes de asistencia mecánica\nRespiradores N95/N100\nPaños de inspección sin pelusa\n\n3. Recocido y control en frío\nLas botellas se enfrían en los hornos de recocido; a continuación, se realizan inspecciones visuales y automatizadas para detectar defectos.\n\n\nPrincipales riesgos:\nGrietas por estrés térmico\nExposición al polvo de vidrio durante el esmerilado o la eliminación de defectos\nRuido elevado procedente de las cintas transportadoras y la maquinaria\n\n\nSoluciones de EPI:\nMangas y guantes resistentes al corte\nRespiradores para polvo y partículas\nProtección auditiva (tapones o orejeras)\nPaños y cepillos de inspección\n\n4. Mantenimiento y reparaciones\nIntervenciones programadas o de emergencia en hornos, arcas de recocido, cintas transportadoras e instalaciones eléctricas.\nLa sustitución de moldes y el cambio de producción representan fases críticas del proceso.\n\n\nPrincipales riesgos:\nEspacios confinados (falta de oxígeno, atmósferas tóxicas)\nDescargas eléctricas y arco eléctrico\nContacto con disolventes y aglutinantes refractarios\nTrabajos en altura\nSoluciones de EPI:\nGuantes aislantes eléctricos (Clase 2/3)\nTrajes y viseras antiarco eléctrico\nArneses anticaídas\nGuantes resistentes a productos químicos y respiradores\nBastoncillos no contaminantes para contactos eléctricos\n\n5. Embalaje, logística y reciclaje\nTras la inspección, las botellas se envasan, paletizan y envían o se destinan al reciclaje; los residuos (calcín, desechos, escorias) se recogen y se preparan para su reutilización.\n\n\nPrincipales riesgos:\nEsfuerzos ergonómicos en la elevación\nRiesgos de aplastamiento y caída de objetos\nAstillas y abrasiones por fragmentos de vidrio\nPolvo y sílice procedentes de material de desecho\nExposición a residuos químicos\n\n\nSoluciones de EPI:\nGuantes ergonómicos antiimpacto\nMangas resistentes al corte y guantes de malla metálica\nCalzado de seguridad con puntera y protección metatarsal\nRespiradores P3/HEPA y gafas de seguridad\nBastoncillos rápidos para muestreo y limpieza"'::jsonb
  ),
  content_locales = COALESCE(content_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"# Industry-Specific PPE Solutions for Glass Manufacturing\n\nHand Line delivers comprehensive personal protective equipment (PPE) solutions tailored to each stage of the glass manufacturing process:\n\n- Raw Material Handling & Batching – Controls silica dust, chemical irritation, and ergonomic strain with P3 respirators, chemical- and ergonomic gloves, and dust swabs.\n- Hot End & Forming – Manages extreme heat, molten spatter, cut risks, and pinch points using aluminized and composite gloves, cotton lubrication swabs, PAPRs, and heat-reflective gear.\n- Annealing & Cold End Inspection – Mitigates stress cracks, glass dust, and noise through cut-resistant PPE, particulate respirators, hearing protection, and precision swabs/brushes.\n- Maintenance & Repair – Protects against electrical hazards, confined spaces, chemicals, and falls with dielectric/arc-flash PPE, harnesses, chemical gloves, respirators, and non-shedding swabs.\n- Packaging, Logistics & Recycling – Addresses ergonomic lifting, crush and cut hazards, dust, and chemical residues via ergonomic impact gloves, chainmail and cut-resistant gear, safety boots, dust respirators, and quick-change swabs.\n\nBy offering gloves, respirators, swabs, and ancillary PPE tailored to each operational risk, Hand Line ensures regulatory compliance, minimizes downtime, and fosters a culture of safety across all production stages.\n\n## 1. Raw Material Handling & Batching\n\nOperators receive, store, and accurately weigh raw ingredients—silica sand, soda ash, limestone, and recycled cullet—often in bulk bags or silos.\n\n### Key Hazards\n- Dust Inhalation: Fine silica and other mineral dusts become airborne during transfer and weighing, posing respiratory and long-term silicosis risks.\n- Ergonomic Strain: Repetitive lifting of heavy sacks or manipulating bulk container fittings can lead to musculoskeletal injuries.\n- Chemical Exposure: Additives (e.g., sodium sulfate, cullet residues) may irritate skin or eyes upon contact.\n\n### PPE Solutions\n- P3/HEPA Respirators or PAPR Units to filter respirable silica and dusts, mitigating inhalation hazards.\n- Chemical-Resistant Gloves (Nitrile/Neoprene) for handling additives that could cause skin irritation.\n- Ergonomic Gloves with Padded Palms to cushion and improve grip, reducing hand fatigue during repetitive movements.\n- High-Efficiency Dust Swabs for sampling and cleaning fine dust accumulations without re-aerosolizing particles.\n\n## 2. Hot End & Forming Operations (Cave-Glass Bottles)\n\nMolten glass is melted in furnaces >1,500 °C, conditioned, and delivered to molds. Workers adjust refractories, stir melts, lubricate molds with cotton swabs; then molten glass is formed into bottles and transferred—manually or robotically—to annealing lehrs.\n\n### Key Hazards\n- Thermal Burns & Radiant Heat: Contact with furnaces, molds, or spatter causes severe burns.\n- Molten Spatter: Droplets of molten glass can eject during stirring or mold filling.\n- Contact Heat During Lubrication: Applying release agents with cotton swabs to hot molds exposes hands to contact and radiant heat.\n- Cut & Abrasion Injuries: Sharp edges on freshly formed bottles or breakages.\n- Crush/Pinch Points: During robotic pick-and-place or manual handling of hot bottles.\n- Fume Exposure: Emissions of silica, metal oxides, and combustion byproducts pose inhalation risks.\n\n### PPE Solutions\n- High-Heat, High-Contact Resistant Gloves: Aluminized, Kevlar-reinforced gauntlets with insulated liners and reinforced back-of-hand protection for mold lubrication and bottle transfers.\n- Cut- & Heat-Resistant Composite Gloves: Combine HPPE fibers and heat-insulating liners to protect against lacerations and surface heat during handling.\n- Cotton Swabs for Mold Lubrication: High-temp cotton swabs designed to carry release agents, resisting degradation and minimizing hand exposure.\n- PAPRs with High-Temperature Silicone Seals: Safe breathing in hot, particulate-laden atmospheres.\n- Heat-Reflective Clothing & Full-Face Shields: Deflect radiant heat and guard against spatter.\n- Mechanical-Assist Transfer Gloves: Improve grip control on hot, slippery surfaces, reducing pinch risks.\n- N95/N100 Respirators: Filter fine glass particulates from mold release agents or dust.\n- Lint-Free Inspection Swabs: For quality checks, ensuring no fibers contaminate the bottle surface.\n\n## 3. Annealing & Cold End Inspection\n\nBottles cool gradually in lehrs; afterwards, visual and automated inspections detect defects.\n\n### Key Hazards\n- Thermal Stress Cracks: Sharp fragments can form as glass cools unevenly.\n- Glass Dust Exposure: Automated grinding or defect removal generates respirable particles.\n- High Noise Levels: Conveyor and inspection machinery contribute to elevated dB levels.\n\n### PPE Solutions\n- Cut-Resistant Sleeves & Gloves to protect against sharp stress cracks during manual inspection.\n- Dust & Particulate Respirators to filter airborne glass dust from grinding and defect removal.\n- Hearing Protection (Earplugs/Earmuffs) to attenuate noise above safe thresholds.\n- Inspection Swabs & Brushes for precise removal of chips without spreading debris.\n\n## 4. Maintenance & Repair Maintenance & Repair. Maintenance & Repair\n\nPlanned or emergency work on furnaces, lehrs, conveyors, and electrical systems.\n\n### Key Hazards\n- Confined Space Entry: Oxygen deficiency or toxic atmospheres in furnace cavities.\n- Electrical Shock & Arc Flash: Live-line work on high-voltage components.\n- Chemical Contact: Cleaning solvents and refractory binders.\n- Height & Fall Risks: Servicing elevated sections of equipment.\n\n### PPE Solutions\n- Dielectric Electrical Gloves (Class 2/3) for energized work up to specified kV.\n- Arc-Flash Rated Suits & Face Shields to guard against flash burns and projectiles.\n- Full-Body Harnesses & Lanyards for fall arrest during elevated maintenance.\n- Chemical-Resistant Gloves & Respirators for solvent handling and fume protection.\n- Non-Shedding Industrial Swabs for cleaning electrical contacts to maintain conductivity.\n\n## 5. Packaging, Logistics & Recycling\n\nAfter inspection, bottles are packed into cartons or crates, palletized, and either shipped or sent for recycling processing. Waste streams (cullet, rejects, slag) are collected, screened, and prepared for reuse.\n\n### Key Hazards\n- Ergonomic Strain: Manual lifting of cases, pallets, and waste containers can cause musculoskeletal injuries.\n- Crush & Drop Hazards: Bottles, cases, pallets, or heavy cullet may fall, risking foot and limb injuries.\n- Sharp Shards & Abrasions: Broken bottles and slag fragments pose cut risks.\n- Dust & Silica Exposure: Handling cullet and rejects generates fine particulates.\n- Chemical Residues: Waste glass may carry residues from prior processing.\n\n### PPE Solutions\n- Ergonomic Impact-Reducing Gloves: Padded gloves to reduce vibration and fatigue during lifting and packing.\n- Cut-Resistant Sleeves & Chainmail Gloves: Combined solutions for forearms and hands to guard against shards.\n- Metatarsal & Steel-Toe Safety Boots: Protect feet from dropped objects and chemical exposure.\n- P3/HEPA Dust Respirators & Safety Glasses: Filter fine dust while shielding eyes from debris.\n- Quick-Change Dust & Contamination Swabs: For swift residue sampling and cleanup without re-aerosolizing particles."'::jsonb,
    'it', '"# Soluzioni DPI Specifiche per l’Industria della Vetreria\n\nHand Line offre soluzioni complete di dispositivi di protezione individuale (DPI) su misura per ciascuna fase del processo di produzione del vetro:\n\n- Gestione e Dosaggio delle Materie Prime\n  Controllo delle polveri di silice, irritazioni chimiche e stress ergonomico con respiratori P3, guanti chimici ed ergonomici e tamponi antipolvere.\n- Forno e Operazioni di Formatura\n  Gestione di calore estremo, schizzi di vetro fuso, rischio di tagli e schiacciamenti con guanti aluminizzati e compositi, tamponi di cotone per lubrificazione, unità PAPR e abbigliamento riflettente.\n- Ricottura e Controllo a Freddo\n  Mitigazione di crepe da stress termico, polveri di vetro e rumore tramite DPI resistenti ai tagli, respiratori per particolato, protezioni acustiche e tamponi/spazzole di precisione.\n- Manutenzione e Riparazioni\n  Protezione da rischi elettrici, spazi confinati, sostanze chimiche e cadute con guanti isolanti/arc-flash, imbracature, guanti chimici, respiratori e tamponi non contaminanti.\n- Imballaggio, Logistica e Riciclaggio\n  Gestione di sollevamenti ergonomici, rischi di schiacciamento e tagli, polveri e residui chimici con guanti antiurto ergonomici, guanti in maglia metallica e resistenti ai tagli, scarpe antinfortunistiche, respiratori P3 e tamponi rapidi.\n\nOffrendo guanti, respiratori, tamponi e altri DPI calibrati sui rischi operativi, Hand Line garantisce conformità normativa, riduce i rischi di fermo impianto e promuove una cultura della sicurezza in tutte le fasi produttive.\n\n## 1. Gestione e Dosaggio delle Materie Prime\n\nGli operatori ricevono, stoccano e pesano con precisione gli ingredienti grezzi — sabbia silice, soda, calcare e vetro riciclato (cullet) — spesso in sacchi sfusi o silos.\n\n### Principali Rischi\n- Inalazione di polveri: Le polveri fini diventano aerodisperse durante trasferimento e pesatura, con rischio respiratorio e di silicosi.\n- Sforzi ergonomici: Sollevamento ripetuto di sacchi pesanti e manipolazione di contenitori sfusi può causare lesioni muscoloscheletriche.\n- Esposizione chimica: Additivi (es. solfato di sodio, residui di cullet) possono irritare pelle e occhi.\n\n### Soluzioni DPI\n- Respiratori P3/HEPA o unità PAPR per filtrare silice e polveri respirabili.\n- Guanti chimico-resistenti (nitrile/neoprene).\n- Guanti ergonomici con palmo imbottito.\n- Tamponi antipolvere ad alta efficienza per campionamento e pulizia.\n\n## 2. Forno e Operazioni di Formatura (Vasi in Vetro)\n\nIl vetro fuso (>1.500 °C) viene condizionato e trasferito negli stampi. Gli operatori regolano i refrattari, mescolano il bagno, lubrificano gli stampi con tamponi di cotone, poi formano le bottiglie e le trasferiscono — manualmente o roboticamente — ai forni di ricottura.\n\n### Principali Rischi\n- Ustioni termiche e calore radiante\n- Schizzi di vetro fuso\n- Calore da contatto durante la lubrificazione\n- Tagli e abrasioni da bordi affilati\n- Schiacciamenti e punti di presa\n- Esposizione a fumi (silice, ossidi metallici)\n\n### Soluzioni DPI\n- Guanti aluminizzati rinforzati in Kevlar con fodera isolante\n- Guanti compositi resistenti a tagli e calore\n- Tamponi di cotone ad alta temperatura\n- PAPRs con guarnizioni in silicone ad alta temperatura\n- Indumenti riflettenti e visiere integrali\n- Guanti meccanici assistiti\n- Respiratori N95/N100\n- Tamponi ispezione senza lanugine\n\n## 3. Ricottura e Controllo a Freddo\n\nLe bottiglie si raffreddano nei forni di ricottura; quindi si effettuano ispezioni visive e automatizzate per rilevare difetti.\n\n### Principali Rischi\n- Crepe da stress termico\n- Esposizione a polveri di vetro durante molatura o rimozione difetti\n- Rumore elevato da nastri e macchinari\n\n### Soluzioni DPI\n- Maniche e guanti resistenti ai tagli\n- Respiratori per polveri e particolato\n- Protezioni auricolari (tappi o cuffie)\n- Tamponi e spazzole di ispezione\n\n## 4. Manutenzione e Riparazioni\n\nInterventi programmati o di emergenza su forni, ricottatori, nastri e impianti elettrici.  \nLa sostituzione degli stampi e il cambio della produzione rappresentano fasi critiche per il processo.\n\n### Principali Rischi\n- Spazi confinati (carenza di ossigeno, atmosfere tossiche)\n- Scosse elettriche e arc-flash\n- Contatto con solventi e leganti refrattari\n- Lavori in quota\n\n### Soluzioni DPI\n- Guanti isolanti elettrici (Classe 2/3)\n- Tute e visiere arc-flash\n- Imbracature anticaduta\n- Guanti chimico-resistenti e respiratori\n- Scovoli non contaminanti per contatti elettrici\n\n## 5. Imballaggio, Logistica e Riciclo\n\nDopo l’ispezione, le bottiglie vengono confezionate, palletizzate e spedite o avviate al riciclo; gli scarti (cullet, scarti, scorie) vengono raccolti e preparati per il riuso.\n\n### Principali Rischi\n- Sforzi ergonomici nel sollevamento\n- Rischi di schiacciamento e caduta di oggetti\n- Schegge e abrasioni da frammenti di vetro\n- Polveri e silice da materiale di scarto\n- Esposizione a residui chimici\n\n### Soluzioni DPI\n- Guanti ergonomici antiurto\n- Maniche resistenti ai tagli e guanti in maglia metallica\n- Scarpe antinfortunistiche con puntale e protezione metatarsale\n- Respiratori P3/HEPA e occhiali di sicurezza\n- Scovoli rapidi per campionamento e pulizia"'::jsonb,
    'fr', '"# Solutions EPI Spécifiques pour l''Industrie du Verre\n\nHand Line propose des solutions complètes d''équipements de protection individuelle (EPI) sur mesure pour chaque étape du processus de production du verre :\n\n- Gestion et Dosage des Matières Premières\n  Contrôle des poussières de silice, des irritations chimiques et du stress ergonomique grâce à des respirateurs P3, des gants chimiques et ergonomiques, et des tampons anti-poussière.\n- Four et Opérations de Formage\n  Gestion de la chaleur extrême, des projections de verre en fusion, des risques de coupures et d''écrasement grâce à des gants aluminisés et composites, des tampons en coton pour la lubrification, des unités PAPR et des vêtements réfléchissants.\n- Recuit et Contrôle à Froid\n  Atténuation des fissures dues au choc thermique, des poussières de verre et du bruit grâce à des EPI résistants aux coupures, des respirateurs anti-particules, des protections auditives et des tampons/brosses de précision.\n- Maintenance et Réparations\n  Protection contre les risques électriques, les espaces confinés, les substances chimiques et les chutes grâce à des gants isolants/anti-arc électrique, des harnais, des gants chimiques, des respirateurs et des tampons non contaminants.\n- Emballage, Logistique et Recyclage\n  Gestion des levages ergonomiques, des risques d''écrasement et de coupure, des poussières et des résidus chimiques grâce à des gants antichocs ergonomiques, des gants en maille métallique et résistants aux coupures, des chaussures de sécurité, des respirateurs P3 et des tampons rapides.\n\nEn proposant des gants, des respirateurs, des tampons et d''autres EPI calibrés en fonction des risques opérationnels, Hand Line garantit la conformité réglementaire, réduit les risques d''arrêt de production et favorise une culture de la sécurité à toutes les étapes de la production.\n\n## 1. Gestion et Dosage des Matières Premières\n\nLes opérateurs réceptionnent, stockent et pèsent avec précision les matières premières — sable siliceux, carbonate de sodium, calcaire et verre recyclé (calcin) — souvent en sacs en vrac ou en silos.\n\n### Principaux Risques\n- Inhalation de poussières : les poussières fines deviennent aéroportées lors du transfert et de la pesée, entraînant un risque respiratoire et de silicose.\n- Efforts ergonomiques : le levage répété de sacs lourds et la manipulation de conteneurs en vrac peuvent provoquer des lésions musculo-squelettiques.\n- Exposition chimique : les additifs (par ex. sulfate de sodium, résidus de calcin) peuvent irriter la peau et les yeux.\n\n### Solutions EPI\n- Respirateurs P3/HEPA ou unités PAPR pour filtrer la silice et les poussières respirables.\n- Gants résistants aux produits chimiques (nitrile/néoprène).\n- Gants ergonomiques à paume rembourrée.\n- Tampons anti-poussière haute efficacité pour l''échantillonnage et le nettoyage.\n\n## 2. Four et Opérations de Formage (Récipients en Verre)\n\nLe verre en fusion (>1 500 °C) est conditionné puis transféré dans les moules. Les opérateurs règlent les réfractaires, brassent le bain, lubrifient les moules avec des tampons en coton, puis forment les bouteilles et les transfèrent — manuellement ou de manière robotisée — vers les fours de recuisson.\n\n### Principaux Risques\n- Brûlures thermiques et chaleur radiante\n- Projections de verre en fusion\n- Chaleur de contact lors de la lubrification\n- Coupures et abrasions dues aux bords tranchants\n- Écrasements et points de pincement\n- Exposition aux fumées (silice, oxydes métalliques)\n\n### Solutions EPI\n- Gants aluminisés renforcés en Kevlar avec doublure isolante\n- Gants composites résistants aux coupures et à la chaleur\n- Tampons en coton résistants aux hautes températures\n- PAPR avec joints en silicone résistants aux hautes températures\n- Vêtements réfléchissants et visières intégrales\n- Gants d''assistance mécanique\n- Respirateurs N95/N100\n- Tampons d''inspection non pelucheux\n\n## 3. Recuit et Contrôle à Froid\n\nLes bouteilles refroidissent dans les fours de recuisson ; des inspections visuelles et automatisées sont ensuite réalisées pour détecter les défauts.\n\n### Principaux Risques\n- Fissures dues au choc thermique\n- Exposition aux poussières de verre lors du meulage ou de l''élimination des défauts\n- Bruit élevé provenant des convoyeurs et des machines\n\n### Solutions EPI\n- Manchettes et gants résistants aux coupures\n- Respirateurs anti-poussières et anti-particules\n- Protections auditives (bouchons ou casques antibruit)\n- Tampons et brosses d''inspection\n\n## 4. Maintenance et Réparations\n\nInterventions programmées ou d''urgence sur les fours, les fours de recuisson, les convoyeurs et les installations électriques.  \nLe remplacement des moules et le changement de production constituent des phases critiques du processus.\n\n### Principaux Risques\n- Espaces confinés (manque d''oxygène, atmosphères toxiques)\n- Chocs électriques et arc électrique\n- Contact avec des solvants et des liants réfractaires\n- Travaux en hauteur\n\n### Solutions EPI\n- Gants isolants électriques (Classe 2/3)\n- Combinaisons et visières anti-arc électrique\n- Harnais antichute\n- Gants résistants aux produits chimiques et respirateurs\n- Écouvillons non contaminants pour contacts électriques\n\n## 5. Emballage, Logistique et Recyclage\n\nAprès l''inspection, les bouteilles sont conditionnées, palettisées puis expédiées ou envoyées au recyclage ; les déchets (calcin, rebuts, scories) sont collectés et préparés pour la réutilisation.\n\n### Principaux Risques\n- Efforts ergonomiques liés au levage\n- Risques d''écrasement et de chute d''objets\n- Éclats et abrasions dus aux fragments de verre\n- Poussières et silice provenant des déchets\n- Exposition à des résidus chimiques\n\n### Solutions EPI\n- Gants ergonomiques antichocs\n- Manchettes résistantes aux coupures et gants en maille métallique\n- Chaussures de sécurité avec embout de protection et protection métatarsienne\n- Respirateurs P3/HEPA et lunettes de sécurité\n- Écouvillons rapides pour l''échantillonnage et le nettoyage"'::jsonb,
    'de', '"# Solutions EPI Spécifiques pour l''Industrie du Verre\n\nHand Line propose des solutions complètes d''équipements de protection individuelle (EPI) sur mesure pour chaque étape du processus de production du verre :\n\n- Gestion et Dosage des Matières Premières\n  Contrôle des poussières de silice, des irritations chimiques et du stress ergonomique grâce à des respirateurs P3, des gants chimiques et ergonomiques, et des tampons anti-poussière.\n- Four et Opérations de Formage\n  Gestion de la chaleur extrême, des projections de verre en fusion, des risques de coupures et d''écrasement grâce à des gants aluminisés et composites, des tampons en coton pour la lubrification, des unités PAPR et des vêtements réfléchissants.\n- Recuit et Contrôle à Froid\n  Atténuation des fissures dues au choc thermique, des poussières de verre et du bruit grâce à des EPI résistants aux coupures, des respirateurs anti-particules, des protections auditives et des tampons/brosses de précision.\n- Maintenance et Réparations\n  Protection contre les risques électriques, les espaces confinés, les substances chimiques et les chutes grâce à des gants isolants/anti-arc électrique, des harnais, des gants chimiques, des respirateurs et des tampons non contaminants.\n- Emballage, Logistique et Recyclage\n  Gestion des levages ergonomiques, des risques d''écrasement et de coupure, des poussières et des résidus chimiques grâce à des gants antichocs ergonomiques, des gants en maille métallique et résistants aux coupures, des chaussures de sécurité, des respirateurs P3 et des tampons rapides.\n\nEn proposant des gants, des respirateurs, des tampons et d''autres EPI calibrés en fonction des risques opérationnels, Hand Line garantit la conformité réglementaire, réduit les risques d''arrêt de production et favorise une culture de la sécurité à toutes les étapes de la production.\n\n## 1. Gestion et Dosage des Matières Premières\n\nLes opérateurs réceptionnent, stockent et pèsent avec précision les matières premières — sable siliceux, carbonate de sodium, calcaire et verre recyclé (calcin) — souvent en sacs en vrac ou en silos.\n\n### Principaux Risques\n- Inhalation de poussières : les poussières fines deviennent aéroportées lors du transfert et de la pesée, entraînant un risque respiratoire et de silicose.\n- Efforts ergonomiques : le levage répété de sacs lourds et la manipulation de conteneurs en vrac peuvent provoquer des lésions musculo-squelettiques.\n- Exposition chimique : les additifs (par ex. sulfate de sodium, résidus de calcin) peuvent irriter la peau et les yeux.\n\n### Solutions EPI\n- Respirateurs P3/HEPA ou unités PAPR pour filtrer la silice et les poussières respirables.\n- Gants résistants aux produits chimiques (nitrile/néoprène).\n- Gants ergonomiques à paume rembourrée.\n- Tampons anti-poussière haute efficacité pour l''échantillonnage et le nettoyage.\n\n## 2. Four et Opérations de Formage (Récipients en Verre)\n\nLe verre en fusion (>1 500 °C) est conditionné puis transféré dans les moules. Les opérateurs règlent les réfractaires, brassent le bain, lubrifient les moules avec des tampons en coton, puis forment les bouteilles et les transfèrent — manuellement ou de manière robotisée — vers les fours de recuisson.\n\n### Principaux Risques\n- Brûlures thermiques et chaleur radiante\n- Projections de verre en fusion\n- Chaleur de contact lors de la lubrification\n- Coupures et abrasions dues aux bords tranchants\n- Écrasements et points de pincement\n- Exposition aux fumées (silice, oxydes métalliques)\n\n### Solutions EPI\n- Gants aluminisés renforcés en Kevlar avec doublure isolante\n- Gants composites résistants aux coupures et à la chaleur\n- Tampons en coton résistants aux hautes températures\n- PAPR avec joints en silicone résistants aux hautes températures\n- Vêtements réfléchissants et visières intégrales\n- Gants d''assistance mécanique\n- Respirateurs N95/N100\n- Tampons d''inspection non pelucheux\n\n## 3. Recuit et Contrôle à Froid\n\nLes bouteilles refroidissent dans les fours de recuisson ; des inspections visuelles et automatisées sont ensuite réalisées pour détecter les défauts.\n\n### Principaux Risques\n- Fissures dues au choc thermique\n- Exposition aux poussières de verre lors du meulage ou de l''élimination des défauts\n- Bruit élevé provenant des convoyeurs et des machines\n\n### Solutions EPI\n- Manchettes et gants résistants aux coupures\n- Respirateurs anti-poussières et anti-particules\n- Protections auditives (bouchons ou casques antibruit)\n- Tampons et brosses d''inspection\n\n## 4. Maintenance et Réparations\n\nInterventions programmées ou d''urgence sur les fours, les fours de recuisson, les convoyeurs et les installations électriques.  \nLe remplacement des moules et le changement de production constituent des phases critiques du processus.\n\n### Principaux Risques\n- Espaces confinés (manque d''oxygène, atmosphères toxiques)\n- Chocs électriques et arc électrique\n- Contact avec des solvants et des liants réfractaires\n- Travaux en hauteur\n\n### Solutions EPI\n- Gants isolants électriques (Classe 2/3)\n- Combinaisons et visières anti-arc électrique\n- Harnais antichute\n- Gants résistants aux produits chimiques et respirateurs\n- Écouvillons non contaminants pour contacts électriques\n\n## 5. Emballage, Logistique et Recyclage\n\nAprès l''inspection, les bouteilles sont conditionnées, palettisées puis expédiées ou envoyées au recyclage ; les déchets (calcin, rebuts, scories) sont collectés et préparés pour la réutilisation.\n\n### Principaux Risques\n- Efforts ergonomiques liés au levage\n- Risques d''écrasement et de chute d''objets\n- Éclats et abrasions dus aux fragments de verre\n- Poussières et silice provenant des déchets\n- Exposition à des résidus chimiques\n\n### Solutions EPI\n- Gants ergonomiques antichocs\n- Manchettes résistantes aux coupures et gants en maille métallique\n- Chaussures de sécurité avec embout de protection et protection métatarsienne\n- Respirateurs P3/HEPA et lunettes de sécurité\n- Écouvillons rapides pour l''échantillonnage et le nettoyage"'::jsonb,
    'es', '"# Soluciones EPI Específicas para la Industria del Vidrio\n\nHand Line ofrece soluciones completas de equipos de protección individual (EPI) a medida para cada fase del proceso de producción del vidrio:\n\n- Gestión y Dosificación de Materias Primas\n  Control del polvo de sílice, las irritaciones químicas y el estrés ergonómico con respiradores P3, guantes químicos y ergonómicos, y paños antipolvo.\n- Horno y Operaciones de Formado\n  Gestión del calor extremo, las salpicaduras de vidrio fundido y el riesgo de cortes y aplastamientos con guantes aluminizados y compuestos, paños de algodón para lubricación, unidades PAPR y ropa reflectante.\n- Recocido y Control en Frío\n  Mitigación de grietas por choque térmico, polvo de vidrio y ruido mediante EPI resistentes al corte, respiradores para partículas, protecciones auditivas y paños/cepillos de precisión.\n- Mantenimiento y Reparaciones\n  Protección frente a riesgos eléctricos, espacios confinados, sustancias químicas y caídas con guantes aislantes/arco eléctrico, arneses, guantes químicos, respiradores y paños no contaminantes.\n- Embalaje, Logística y Reciclaje\n  Gestión de levantamientos ergonómicos, riesgos de aplastamiento y corte, polvo y residuos químicos con guantes ergonómicos anti-impacto, guantes de malla metálica y resistentes al corte, calzado de seguridad, respiradores P3 y paños rápidos.\n\nAl ofrecer guantes, respiradores, paños y otros EPI calibrados según los riesgos operativos, Hand Line garantiza el cumplimiento normativo, reduce los riesgos de parada de la planta y promueve una cultura de seguridad en todas las fases de producción.\n\n## 1. Gestión y Dosificación de Materias Primas\n\nLos operarios reciben, almacenan y pesan con precisión las materias primas — arena de sílice, sosa, caliza y vidrio reciclado (calcín) — a menudo en sacos a granel o silos.\n\n### Principales Riesgos\n- Inhalación de polvo: el polvo fino se dispersa en el aire durante el transporte y el pesaje, con riesgo respiratorio y de silicosis.\n- Esfuerzos ergonómicos: el levantamiento repetido de sacos pesados y la manipulación de contenedores a granel pueden causar lesiones musculoesqueléticas.\n- Exposición química: los aditivos (por ejemplo, sulfato de sodio, residuos de calcín) pueden irritar la piel y los ojos.\n\n### Soluciones EPI\n- Respiradores P3/HEPA o unidades PAPR para filtrar la sílice y el polvo respirable.\n- Guantes resistentes a productos químicos (nitrilo/neopreno).\n- Guantes ergonómicos con palma acolchada.\n- Paños antipolvo de alta eficiencia para muestreo y limpieza.\n\n## 2. Horno y Operaciones de Formado (Envases de Vidrio)\n\nEl vidrio fundido (>1.500 °C) se acondiciona y se transfiere a los moldes. Los operarios ajustan los refractarios, agitan el baño, lubrican los moldes con paños de algodón y luego forman las botellas y las transfieren — manualmente o mediante robots — a los hornos de recocido.\n\n### Principales Riesgos\n- Quemaduras térmicas y calor radiante\n- Salpicaduras de vidrio fundido\n- Calor por contacto durante la lubricación\n- Cortes y abrasiones por bordes afilados\n- Aplastamientos y puntos de atrapamiento\n- Exposición a humos (sílice, óxidos metálicos)\n\n### Soluciones EPI\n- Guantes aluminizados reforzados con Kevlar y forro aislante\n- Guantes compuestos resistentes a cortes y al calor\n- Paños de algodón para altas temperaturas\n- PAPR con juntas de silicona para altas temperaturas\n- Ropa reflectante y viseras integrales\n- Guantes de asistencia mecánica\n- Respiradores N95/N100\n- Paños de inspección sin pelusa\n\n## 3. Recocido y Control en Frío\n\nLas botellas se enfrían en los hornos de recocido; a continuación, se realizan inspecciones visuales y automatizadas para detectar defectos.\n\n### Principales Riesgos\n- Grietas por choque térmico\n- Exposición a polvo de vidrio durante el esmerilado o la eliminación de defectos\n- Ruido elevado procedente de las cintas transportadoras y la maquinaria\n\n### Soluciones EPI\n- Mangas y guantes resistentes al corte\n- Respiradores para polvo y partículas\n- Protecciones auditivas (tapones o orejeras)\n- Paños y cepillos de inspección\n\n## 4. Mantenimiento y Reparaciones\n\nIntervenciones programadas o de emergencia en hornos, hornos de recocido, cintas transportadoras e instalaciones eléctricas.  \nLa sustitución de los moldes y el cambio de producción representan fases críticas del proceso.\n\n### Principales Riesgos\n- Espacios confinados (falta de oxígeno, atmósferas tóxicas)\n- Descargas eléctricas y arco eléctrico\n- Contacto con disolventes y aglutinantes refractarios\n- Trabajos en altura\n\n### Soluciones EPI\n- Guantes aislantes eléctricos (Clase 2/3)\n- Trajes y viseras contra arco eléctrico\n- Arneses anticaídas\n- Guantes resistentes a productos químicos y respiradores\n- Escobillas no contaminantes para contactos eléctricos\n\n## 5. Embalaje, Logística y Reciclaje\n\nTras la inspección, las botellas se envasan, se paletizan y se envían o se destinan al reciclaje; los residuos (calcín, desechos, escoria) se recogen y se preparan para su reutilización.\n\n### Principales Riesgos\n- Esfuerzos ergonómicos en el levantamiento\n- Riesgos de aplastamiento y caída de objetos\n- Astillas y abrasiones por fragmentos de vidrio\n- Polvo y sílice procedentes de material de desecho\n- Exposición a residuos químicos\n\n### Soluciones EPI\n- Guantes ergonómicos anti-impacto\n- Mangas resistentes al corte y guantes de malla metálica\n- Calzado de seguridad con puntera y protección metatarsiana\n- Respiradores P3/HEPA y gafas de seguridad\n- Escobillas rápidas para muestreo y limpieza"'::jsonb
  ),
  features_locales = COALESCE(features_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '["Advanced thermal protection maintaining dexterity up to 1000°C in Hot End operations", "Specialized silicone grip pattern for secure handling of glass products", "Seamless liner construction to prevent glass fiber contamination", "Extended gauntlet design with reinforced wrist protection"]'::jsonb,
    'it', '["Protezione termica avanzata mantenendo destrezza fino a 1000°C nelle operazioni Hot End", "Motivo di presa in silicone specializzato per manipolazione sicura dei prodotti in vetro", "Costruzione del rivestimento senza cuciture per prevenire contaminazione da fibra di vetro", "Design del guanto esteso con protezione rinforzata del polso"]'::jsonb,
    'fr', '["Protection thermique avancée tout en conservant la dextérité jusqu''à 1000°C dans les opérations Hot End", "Motif de préhension en silicone spécialisé pour une manipulation sûre des produits en verre", "Construction du revêtement sans couture pour prévenir la contamination par fibres de verre", "Conception de gant prolongé avec protection renforcée du poignet"]'::jsonb,
    'de', '["Fortschrittlicher Hitzeschutz bei gleichzeitig erhaltener Fingerfertigkeit bis zu 1000 °C bei Hot-End-Vorgängen", "Spezialisiertes Silikon-Griffmuster für die sichere Handhabung von Glasprodukten", "Nahtlose Beschichtungskonstruktion zur Vermeidung von Glasfaserkontamination", "Verlängertes Handschuhdesign mit verstärktem Handgelenkschutz"]'::jsonb,
    'es', '["Protección térmica avanzada manteniendo la destreza hasta 1000 °C en las operaciones Hot End", "Patrón de agarre de silicona especializado para la manipulación segura de productos de vidrio", "Construcción del revestimiento sin costuras para prevenir la contaminación por fibra de vidrio", "Diseño de guante extendido con protección reforzada de la muñeca"]'::jsonb
  ),
  showcase_description_locales = COALESCE(showcase_description_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Glass manufacturing encompasses multiple high-risk stages—from handling silica-rich raw materials to extreme-temperature forming, precision inspection, maintenance, and logistics—each posing unique hazards like dust inhalation, thermal burns, mechanical injuries, and chemical exposures. With over 40 years of experience designing and supplying safety solutions specifically for large glass manufacturers, our range of products can cover all needs."'::jsonb,
    'it', '"La produzione del vetro comprende diverse fasi ad alto rischio — dalla gestione di materie prime ricche di silice alla formatura ad alte temperature, fino all’ispezione di precisione, alla manutenzione e alla logistica — ciascuna con pericoli specifici come l’inalazione di polveri, ustioni termiche, infortuni meccanici ed esposizioni chimiche. Con oltre 40 anni di esperienza nella progettazione e fornitura di soluzioni di sicurezza specifiche per i grandi produttori di vetro, la nostra gamma di prodotti è in grado di coprire ogni esigenza."'::jsonb,
    'fr', '"La production du verre comprend plusieurs phases à haut risque — de la gestion des matières premières riches en silice à la formation à haute température, jusqu''à l''inspection de précision, à la maintenance et à la logistique — chacune présentant des dangers spécifiques tels que l''inhalation de poussières, les brûlures thermiques, les blessures mécaniques et les expositions chimiques. Avec plus de 40 ans d''expérience dans la conception et la fourniture de solutions de sécurité spécifiques pour les grands fabricants de verre, notre gamme de produits est en mesure de couvrir tous les besoins."'::jsonb,
    'de', '"Die Glasproduktion umfasst mehrere Hochrisikophasen — von der Handhabung kieselsäurereicher Rohstoffe über die Formgebung bei hohen Temperaturen bis hin zur Präzisionsprüfung, Wartung und Logistik — jede mit spezifischen Gefahren wie Staubinhalation, thermischen Verbrennungen, mechanischen Verletzungen und chemischen Expositionen. Mit über 40 Jahren Erfahrung in der Entwicklung und Bereitstellung von Sicherheitslösungen speziell für große Glashersteller deckt unser Produktsortiment jeden Bedarf ab."'::jsonb,
    'es', '"La producción de vidrio comprende varias fases de alto riesgo — desde la gestión de materias primas ricas en sílice hasta el moldeado a altas temperaturas, pasando por la inspección de precisión, el mantenimiento y la logística — cada una con peligros específicos como la inhalación de polvo, quemaduras térmicas, lesiones mecánicas y exposiciones químicas. Con más de 40 años de experiencia en el diseño y suministro de soluciones de seguridad específicas para los grandes fabricantes de vidrio, nuestra gama de productos es capaz de cubrir cualquier necesidad."'::jsonb
  ),
  summary_content_locales = COALESCE(summary_content_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Glass manufacturing encompasses multiple high-risk stages—from handling silica-rich raw materials to extreme-temperature forming, precision inspection, maintenance, and logistics—each posing unique hazards like dust inhalation, thermal burns, mechanical injuries, and chemical exposures. Ensuring worker safety demands stage-specific PPE solutions such as respirators, heat-resistant and cut-protective gloves, hearing protection, and ergonomic equipment."'::jsonb,
    'it', '"La produzione del vetro comprende fasi ad alto rischio – dalla gestione delle materie prime ricche di silice alla formatura ad alte temperature, dal controllo di qualità alla manutenzione e alla logistica – con pericoli quali inalazione di polveri, ustioni termiche, lesioni meccaniche ed esposizioni chimiche. La sicurezza richiede DPI specifici per ogni fase, come respiratori, guanti resistenti al calore e ai tagli, protezioni acustiche ed equipaggiamento ergonomico."'::jsonb,
    'fr', '"La production du verre comprend des phases à haut risque – de la gestion des matières premières riches en silice à la formation à haute température, du contrôle qualité à la maintenance et à la logistique – avec des dangers tels que l''inhalation de poussières, les brûlures thermiques, les blessures mécaniques et les expositions chimiques. La sécurité exige des EPI spécifiques à chaque phase, tels que des appareils respiratoires, des gants résistants à la chaleur et aux coupures, des protections auditives et des équipements ergonomiques."'::jsonb,
    'de', '"Die Glasproduktion umfasst Hochrisikophasen – von der Handhabung kieselsäurereicher Rohstoffe über die Formgebung bei hohen Temperaturen bis zur Qualitätskontrolle, Wartung und Logistik – mit Gefahren wie Staubinhalation, thermischen Verbrennungen, mechanischen Verletzungen und chemischen Expositionen. Die Sicherheit erfordert phasenspezifische PSA wie Atemschutzgeräte, hitze- und schnittbeständige Handschuhe, Gehörschutz und ergonomische Ausrüstung."'::jsonb,
    'es', '"La producción de vidrio comprende fases de alto riesgo – desde la gestión de materias primas ricas en sílice hasta el moldeado a altas temperaturas, pasando por el control de calidad, el mantenimiento y la logística – con peligros como la inhalación de polvo, quemaduras térmicas, lesiones mecánicas y exposiciones químicas. La seguridad requiere EPI específicos para cada fase, como equipos de protección respiratoria, guantes resistentes al calor y a los cortes, protección auditiva y equipamiento ergonómico."'::jsonb
  ),
  sections_locales = COALESCE(sections_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '[{"title": "Raw Material Handling & Batching", "description": "Operators receive, store and accurately weigh bulk ingredients—silica sand, soda ash, limestone, and recycled cullet—often transferring materials between bags, silos and hoppers. This stage requires constant vigilance to prevent respirable dust generation and to maintain ergonomic handling practices.\n\nProper PPE at this step not only protects against inhalation and skin irritation but also reduces fatigue and musculoskeletal strain, ensuring consistent accuracy in batching operations.", "key_hazards": ["Dust inhalation of respirable silica", "Ergonomic strain from repetitive lifting", "Skin and eye irritation from chemical additives"], "ppe_solutions": ["P3/HEPA respirators or PAPR units", "Chemical-resistant nitrile or neoprene gloves", "Ergonomic gloves with padded palms", "High-efficiency dust sampling swabs"]}, {"title": "Hot End & Forming Operations (Cave-Glass Bottles)", "description": "Molten glass (>1,500°C) is conditioned in furnaces and formed into bottles, with workers adjusting refractories, stirring melts and lubricating molds before transfer to annealing lehrs. Manual and robotic handling of hot, viscous glass demands precise control and protection.\n\nAt this stage, PPE must guard against radiant and contact heat, molten spatter, sharp edges, pinch points and airborne fume exposures, while allowing sufficient dexterity for mold lubrication and inspection.", "key_hazards": ["Thermal burns and radiant heat", "Molten glass spatter", "Contact heat during mold lubrication", "Cut and abrasion injuries", "Crush/pinch points", "Fume exposure"], "ppe_solutions": ["Aluminized, Kevlar-reinforced high-heat gauntlets", "Cut- & heat-resistant composite gloves", "High-temperature cotton lubrication swabs", "PAPR units with silicone high-temp seals", "Heat-reflective clothing and full-face shields", "Mechanical-assist transfer gloves"]}, {"title": "Annealing & Cold End Inspection", "description": "After gradual cooling in annealing lehrs, bottles undergo visual and automated inspections to detect defects like stress cracks or surface irregularities. Grinding or defect removal can generate fine glass dust and high noise levels.\n\nEffective PPE here focuses on cut protection, respiratory filtration and hearing conservation, enabling inspectors to work safely and maintain product quality.", "key_hazards": ["Thermal stress cracks", "Glass dust exposure", "High noise levels"], "ppe_solutions": ["Cut-resistant sleeves and gloves", "Particulate respirators", "Earplugs or earmuffs", "Precision inspection swabs and brushes"]}, {"title": "Maintenance & Repair", "description": "Routine and emergency maintenance on furnaces, conveyors, lehrs and electrical systems involves confined-space entry, live-line work and working at heights. Technicians may also handle solvents and refractory binders.\n\nComprehensive PPE—ranging from dielectric gloves to arc-flash suits, fall-arrest gear and chemical protection—is critical to prevent serious injuries during these high-risk interventions.", "key_hazards": ["Confined space atmospheres", "Electrical shock and arc flash", "Chemical contact", "Height and fall risks"], "ppe_solutions": ["Class 2/3 dielectric electrical gloves", "Arc-flash rated suits and face shields", "Full-body harnesses and lanyards", "Chemical-resistant gloves and respirators", "Non-shedding industrial swabs"]}, {"title": "Packaging, Logistics & Recycling", "description": "Finished bottles are packed, palletized and shipped or routed to recycling. Waste cullet, rejects and slag are screened and reprocessed. Manual handling of cases, pallets and material streams creates ergonomic, crush and cut hazards, alongside dust and residual chemicals.\n\nPPE solutions here combine impact-reducing and cut-protection gloves, safety boots, dust respirators and quick-change swabs to maintain productivity and safeguard workers in dynamic material-handling environments.", "key_hazards": ["Ergonomic strain from lifting", "Crush and drop hazards", "Sharp shards and abrasions", "Dust and silica exposure", "Chemical residue contact"], "ppe_solutions": ["Ergonomic impact-reducing gloves", "Cut-resistant chainmail gloves and sleeves", "Steel-toe and metatarsal safety boots", "P3/HEPA dust respirators and safety glasses", "Quick-change dust and contamination swabs"]}]'::jsonb,
    'it', '[{"title": "Gestione e Dosaggio delle Materie Prime", "description": "Gli operatori ricevono, stoccano e pesano con precisione sabbia di silice, soda, calcare e vetro riciclato (cullet), trasferendo materiali tra sacchi, silos e tramogge. Questa fase richiede misure per evitare la dispersione di polveri e per favorire posture ergonomiche.\n\nL’uso di DPI adeguati protegge dall’inalazione, dalle irritazioni cutanee e riduce l’affaticamento muscolare, garantendo operazioni di dosaggio accurate.", "key_hazards": ["Inalazione di polveri di silice", "Sforzi ergonomici da sollevamento ripetuto", "Irritazione cutanea e oculare da additivi"], "ppe_solutions": ["Respiratori P3/HEPA o unità PAPR", "Guanti chimico-resistenti (nitrile/neoprene)", "Guanti ergonomici con palmo imbottito", "Tamponi antipolvere ad alta efficienza"]}, {"title": "Operazioni Hot End e di Formatura (Bottiglie in Vetro Cave)", "description": "Il vetro fuso (>1 500 °C) viene condizionato e trasferito negli stampi; gli operatori regolano refrattari, mescolano il bagno e lubrificano gli stampi prima del trasferimento ai forni di ricottura. La manipolazione manuale e robotica richiede precisione e protezione.\n\nI DPI in questa fase devono proteggere da calore radiante e di contatto, schizzi di vetro fuso, bordi taglienti, punti di schiacciamento e fumi, garantendo però destrezza per lubrificare e ispezionare gli stampi.", "key_hazards": ["Ustioni termiche e calore radiante", "Schizzi di vetro fuso", "Calore da contatto durante la lubrificazione", "Tagli e abrasioni", "Punti di schiacciamento", "Esposizione a fumi"], "ppe_solutions": ["Guanti aluminizzati rinforzati in Kevlar", "Guanti compositi resistenti a tagli e calore", "Tamponi di cotone ad alta temperatura", "Unità PAPR con guarnizioni in silicone ad alta temperatura", "Indumenti riflettenti e visiere integrali", "Guanti meccanici assistiti"]}, {"title": "Ricottura e Controllo a Freddo", "description": "Dopo il raffreddamento nei forni di ricottura, le bottiglie vengono ispezionate visivamente e con macchine automatiche per individuare crepe e difetti. Operazioni di molatura o rimozione difetti generano polveri di vetro e rumore elevato.\n\nI DPI qui sono focalizzati su protezione da tagli, filtrazione delle polveri e attenuazione del rumore, permettendo ispezioni sicure e di qualità.", "key_hazards": ["Crepe da stress termico", "Esposizione a polveri di vetro", "Rumore elevato"], "ppe_solutions": ["Maniche e guanti resistenti ai tagli", "Respiratori per particolato", "Tappi o cuffie antirumore", "Tamponi e spazzole di precisione"]}, {"title": "Manutenzione e Riparazioni", "description": "Le attività di manutenzione programmata o di emergenza su forni, nastri trasportatori, ricottatori e impianti elettrici comportano l’accesso a spazi confinati, il lavoro su linee energizzate e operazioni in quota. Si utilizzano anche solventi e leganti refrattari.\n\nI DPI completi—dai guanti isolanti agli indumenti arc-flash, imbracature anticaduta e protezioni chimiche—sono essenziali per prevenire infortuni gravi.", "key_hazards": ["Spazi confinati", "Scosse elettriche e arc-flash", "Contatto con sostanze chimiche", "Lavori in quota"], "ppe_solutions": ["Guanti isolanti elettrici Classe 2/3", "Tute e visiere arc-flash", "Imbracature anticaduta", "Guanti chimico-resistenti e respiratori", "Scovoli non contaminanti"]}, {"title": "Imballaggio, Logistica e Riciclo", "description": "Le bottiglie finite vengono confezionate, palletizzate e spedite o inviate al riciclo; gli scarti di cullet e scorie sono selezionati e riutilizzati. La movimentazione manuale di casi, pallet e materiali implica rischi ergonomici, di schiacciamento e di taglio, oltre a polveri e residui chimici.\n\nI DPI per questa fase combinano guanti antiurto ed anti-taglio, calzature di sicurezza, respiratori e tamponi rapidi per mantenere efficienza e protezione in un ambiente dinamico.", "key_hazards": ["Sforzi ergonomici da sollevamento", "Rischi di schiacciamento", "Schegge e abrasioni", "Polveri e silice", "Residui chimici"], "ppe_solutions": ["Guanti ergonomici antiurto", "Guanti in maglia metallica e maniche resistenti ai tagli", "Scarpe antinfortunistiche con puntale e protezione metatarsale", "Respiratori P3/HEPA e occhiali di sicurezza", "Tamponi rapidi per pulizia"]}]'::jsonb,
    'fr', '[{"title": "Gestion et dosage des matières premières", "description": "Les opérateurs reçoivent, stockent et pèsent avec précision du sable de silice, de la soude, du calcaire et du verre recyclé (calcin), en transférant les matériaux entre sacs, silos et trémies. Cette phase nécessite des mesures pour éviter la dispersion des poussières et favoriser des postures ergonomiques.\n\nL''utilisation d''EPI adaptés protège contre l''inhalation et les irritations cutanées et réduit la fatigue musculaire, garantissant des opérations de dosage précises.", "key_hazards": ["Inhalation de poussières de silice", "Contraintes ergonomiques dues au levage répété", "Irritation cutanée et oculaire due aux additifs"], "ppe_solutions": ["Appareils respiratoires P3/HEPA ou unités PAPR", "Gants résistants aux produits chimiques (nitrile/néoprène)", "Gants ergonomiques à paume rembourrée", "Tampons antipoussière à haute efficacité"]}, {"title": "Opérations de zone chaude et de formage (bouteilles en verre creux)", "description": "Le verre fondu (>1 500 °C) est conditionné et transféré dans les moules ; les opérateurs règlent les réfractaires, mélangent le bain et lubrifient les moules avant le transfert vers les fours de recuisson. La manipulation manuelle et robotisée exige précision et protection.\n\nÀ cette phase, les EPI doivent protéger contre la chaleur radiante et de contact, les projections de verre fondu, les arêtes tranchantes, les points d''écrasement et les fumées, tout en garantissant la dextérité nécessaire pour lubrifier et inspecter les moules.", "key_hazards": ["Brûlures thermiques et chaleur radiante", "Projections de verre fondu", "Chaleur de contact pendant la lubrification", "Coupures et abrasions", "Points d''écrasement", "Exposition aux fumées"], "ppe_solutions": ["Gants aluminisés renforcés en Kevlar", "Gants composites résistants aux coupures et à la chaleur", "Tampons en coton résistants aux hautes températures", "Unités PAPR avec joints en silicone haute température", "Vêtements réfléchissants et visières intégrales", "Gants à assistance mécanique"]}, {"title": "Recuisson et contrôle à froid", "description": "Après le refroidissement dans les fours de recuisson, les bouteilles sont inspectées visuellement et par des machines automatiques afin de détecter fissures et défauts. Les opérations de meulage ou d''élimination des défauts génèrent des poussières de verre et un bruit élevé.\n\nIci, les EPI sont axés sur la protection contre les coupures, la filtration des poussières et l''atténuation du bruit, permettant des inspections sûres et de qualité.", "key_hazards": ["Fissures dues au stress thermique", "Exposition aux poussières de verre", "Bruit élevé"], "ppe_solutions": ["Manchettes et gants résistants aux coupures", "Appareils respiratoires anti-particules", "Bouchons ou casques antibruit", "Tampons et brosses de précision"]}, {"title": "Maintenance et réparations", "description": "Les activités de maintenance programmée ou d''urgence sur les fours, convoyeurs, arches de recuisson et installations électriques impliquent l''accès à des espaces confinés, le travail sur des lignes sous tension et des opérations en hauteur. Des solvants et des liants réfractaires sont également utilisés.\n\nDes EPI complets—des gants isolants aux vêtements arc-flash, en passant par les harnais antichute et les protections chimiques—sont essentiels pour prévenir les blessures graves.", "key_hazards": ["Espaces confinés", "Chocs électriques et arc électrique (arc-flash)", "Contact avec des substances chimiques", "Travaux en hauteur"], "ppe_solutions": ["Gants isolants électriques Classe 2/3", "Combinaisons et visières arc-flash", "Harnais antichute", "Gants résistants aux produits chimiques et appareils respiratoires", "Écouvillons non contaminants"]}, {"title": "Emballage, logistique et recyclage", "description": "Les bouteilles finies sont conditionnées, palettisées et expédiées ou envoyées au recyclage ; les déchets de calcin et de scories sont triés et réutilisés. La manutention manuelle des caisses, palettes et matériaux implique des risques ergonomiques, d''écrasement et de coupure, ainsi que des poussières et des résidus chimiques.\n\nPour cette phase, les EPI associent gants anti-chocs et anticoupure, chaussures de sécurité, appareils respiratoires et lingettes rapides afin de maintenir efficacité et protection dans un environnement dynamique.", "key_hazards": ["Contraintes ergonomiques dues au levage", "Risques d''écrasement", "Éclats et abrasions", "Poussières et silice", "Résidus chimiques"], "ppe_solutions": ["Gants ergonomiques anti-chocs", "Gants en maille métallique et manchettes résistantes aux coupures", "Chaussures de sécurité à embout et protection métatarsienne", "Appareils respiratoires P3/HEPA et lunettes de sécurité", "Lingettes de nettoyage rapide"]}]'::jsonb,
    'de', '[{"title": "Handhabung und Dosierung der Rohstoffe", "description": "Die Bediener nehmen Quarzsand, Soda, Kalkstein und recyceltes Glas (Scherben) entgegen, lagern und wiegen sie präzise ab und transportieren die Materialien zwischen Säcken, Silos und Trichtern. Diese Phase erfordert Maßnahmen zur Vermeidung von Staubverbreitung und zur Förderung ergonomischer Körperhaltungen.\n\nDer Einsatz geeigneter PSA schützt vor Inhalation und Hautreizungen und reduziert die Muskelermüdung, wodurch präzise Dosiervorgänge gewährleistet werden.", "key_hazards": ["Einatmen von Kieselstaub", "Ergonomische Belastung durch wiederholtes Heben", "Haut- und Augenreizungen durch Zusatzstoffe"], "ppe_solutions": ["P3/HEPA-Atemschutzgeräte oder PAPR-Einheiten", "Chemikalienbeständige Handschuhe (Nitril/Neopren)", "Ergonomische Handschuhe mit gepolsterter Handfläche", "Hocheffiziente Staubschutztücher"]}, {"title": "Hot-End- und Formgebungsvorgänge (Hohlglasflaschen)", "description": "Das geschmolzene Glas (>1.500 °C) wird konditioniert und in Formen überführt; die Bediener regulieren die feuerfesten Materialien, mischen das Bad und schmieren die Formen vor dem Transfer in die Kühlöfen. Die manuelle und robotergestützte Handhabung erfordert Präzision und Schutz.\n\nDie PSA in dieser Phase müssen vor Strahlungs- und Kontaktwärme, Spritzern von geschmolzenem Glas, scharfen Kanten, Quetschstellen und Dämpfen schützen und dabei die für das Schmieren und Prüfen der Formen nötige Fingerfertigkeit gewährleisten.", "key_hazards": ["Thermische Verbrennungen und Strahlungswärme", "Spritzer von geschmolzenem Glas", "Kontaktwärme beim Schmieren", "Schnitte und Abschürfungen", "Quetschstellen", "Rauchexposition"], "ppe_solutions": ["Aluminisierte, mit Kevlar verstärkte Handschuhe", "Verbundhandschuhe, schnitt- und hitzebeständig", "Hochtemperaturbeständige Baumwolltücher", "PAPR-Einheiten mit hochtemperaturbeständigen Silikondichtungen", "Reflektierende Kleidung und Vollvisiere", "Mechanisch unterstützte Handschuhe"]}, {"title": "Kühlen und Kaltkontrolle", "description": "Nach der Abkühlung in den Kühlöfen werden die Flaschen visuell und mittels automatischer Maschinen auf Risse und Defekte geprüft. Schleif- oder Fehlerbeseitigungsarbeiten erzeugen Glasstaub und hohen Lärm.\n\nDie PSA konzentrieren sich hier auf Schnittschutz, Staubfilterung und Lärmminderung und ermöglichen sichere und qualitativ hochwertige Prüfungen.", "key_hazards": ["Risse durch thermische Spannung", "Exposition gegenüber Glasstaub", "Hoher Lärmpegel"], "ppe_solutions": ["Schnittschutzärmel und -handschuhe", "Partikel-Atemschutzgeräte", "Gehörschutzstöpsel oder Kapselgehörschutz", "Präzisionstücher und -bürsten"]}, {"title": "Wartung und Reparaturen", "description": "Geplante oder Notfallwartungsarbeiten an Öfen, Förderbändern, Kühlöfen und elektrischen Anlagen erfordern den Zugang zu engen Räumen, Arbeiten an spannungsführenden Leitungen und Arbeiten in der Höhe. Zudem werden Lösungsmittel und feuerfeste Bindemittel verwendet.\n\nVollständige PSA — von Isolierhandschuhen über Arc-Flash-Kleidung bis hin zu Absturzsicherungsgeschirren und chemischem Schutz — sind unerlässlich, um schwere Verletzungen zu verhindern.", "key_hazards": ["Enge Räume", "Stromschläge und Lichtbogen (Arc-Flash)", "Kontakt mit Chemikalien", "Arbeiten in der Höhe"], "ppe_solutions": ["Elektrisch isolierende Handschuhe Klasse 2/3", "Arc-Flash-Anzüge und -Visiere", "Absturzsicherungsgeschirre", "Chemikalienbeständige Handschuhe und Atemschutzgeräte", "Kontaminationsfreie Reinigungsbürsten"]}, {"title": "Verpackung, Logistik und Recycling", "description": "Die fertigen Flaschen werden verpackt, palettiert und versandt oder dem Recycling zugeführt; Scherben- und Schlackenreste werden sortiert und wiederverwendet. Die manuelle Handhabung von Kisten, Paletten und Materialien birgt ergonomische Risiken sowie Quetsch- und Schnittgefahren zusätzlich zu Staub und chemischen Rückständen.\n\nDie PSA für diese Phase kombinieren stoß- und schnittfeste Handschuhe, Sicherheitsschuhe, Atemschutzgeräte und Schnellreinigungstücher, um Effizienz und Schutz in einer dynamischen Umgebung zu gewährleisten.", "key_hazards": ["Ergonomische Belastung durch Heben", "Quetschgefahren", "Splitter und Abschürfungen", "Staub und Kieselsäure", "Chemische Rückstände"], "ppe_solutions": ["Ergonomische Stoßschutzhandschuhe", "Handschuhe aus Metallgewebe und Schnittschutzärmel", "Sicherheitsschuhe mit Zehenschutzkappe und Mittelfußschutz", "P3/HEPA-Atemschutzgeräte und Schutzbrillen", "Schnellreinigungstücher"]}]'::jsonb,
    'es', '[{"title": "Gestión y dosificación de las materias primas", "description": "Los operarios reciben, almacenan y pesan con precisión arena de sílice, sosa, caliza y vidrio reciclado (calcín), transfiriendo materiales entre sacos, silos y tolvas. Esta fase requiere medidas para evitar la dispersión de polvo y favorecer posturas ergonómicas.\n\nEl uso de EPI adecuados protege frente a la inhalación y las irritaciones cutáneas y reduce la fatiga muscular, garantizando operaciones de dosificación precisas.", "key_hazards": ["Inhalación de polvo de sílice", "Esfuerzos ergonómicos por levantamiento repetido", "Irritación cutánea y ocular por aditivos"], "ppe_solutions": ["Equipos de protección respiratoria P3/HEPA o unidades PAPR", "Guantes resistentes a productos químicos (nitrilo/neopreno)", "Guantes ergonómicos con palma acolchada", "Paños antipolvo de alta eficacia"]}, {"title": "Operaciones de zona caliente y moldeado (botellas de vidrio hueco)", "description": "El vidrio fundido (>1.500 °C) se acondiciona y se transfiere a los moldes; los operarios ajustan los refractarios, mezclan el baño y lubrican los moldes antes de transferirlos a los hornos de recocido. La manipulación manual y robótica requiere precisión y protección.\n\nEn esta fase, los EPI deben proteger frente al calor radiante y de contacto, las salpicaduras de vidrio fundido, los bordes cortantes, los puntos de aplastamiento y los humos, garantizando al mismo tiempo la destreza necesaria para lubricar e inspeccionar los moldes.", "key_hazards": ["Quemaduras térmicas y calor radiante", "Salpicaduras de vidrio fundido", "Calor por contacto durante la lubricación", "Cortes y abrasiones", "Puntos de aplastamiento", "Exposición a humos"], "ppe_solutions": ["Guantes aluminizados reforzados con Kevlar", "Guantes compuestos resistentes a los cortes y al calor", "Paños de algodón resistentes a altas temperaturas", "Unidades PAPR con juntas de silicona de alta temperatura", "Ropa reflectante y viseras integrales", "Guantes con asistencia mecánica"]}, {"title": "Recocido y control en frío", "description": "Después del enfriamiento en los hornos de recocido, las botellas se inspeccionan visualmente y mediante máquinas automáticas para detectar grietas y defectos. Las operaciones de esmerilado o eliminación de defectos generan polvo de vidrio y ruido elevado.\n\nAquí, los EPI se centran en la protección frente a cortes, la filtración de polvo y la atenuación del ruido, permitiendo inspecciones seguras y de calidad.", "key_hazards": ["Grietas por estrés térmico", "Exposición al polvo de vidrio", "Ruido elevado"], "ppe_solutions": ["Mangas y guantes resistentes a los cortes", "Equipos de protección respiratoria contra partículas", "Tapones o auriculares antirruido", "Paños y cepillos de precisión"]}, {"title": "Mantenimiento y reparaciones", "description": "Las actividades de mantenimiento programado o de emergencia en hornos, cintas transportadoras, arcas de recocido e instalaciones eléctricas implican el acceso a espacios confinados, el trabajo en líneas energizadas y operaciones en altura. También se utilizan disolventes y aglutinantes refractarios.\n\nLos EPI completos —desde guantes aislantes hasta ropa arc-flash, arneses anticaídas y protecciones químicas— son esenciales para prevenir lesiones graves.", "key_hazards": ["Espacios confinados", "Descargas eléctricas y arco eléctrico (arc-flash)", "Contacto con sustancias químicas", "Trabajos en altura"], "ppe_solutions": ["Guantes aislantes eléctricos Clase 2/3", "Trajes y viseras arc-flash", "Arneses anticaídas", "Guantes resistentes a productos químicos y equipos de protección respiratoria", "Escobillas no contaminantes"]}, {"title": "Embalaje, logística y reciclaje", "description": "Las botellas terminadas se embalan, se paletizan y se envían o se destinan al reciclaje; los residuos de calcín y escoria se seleccionan y se reutilizan. La manipulación manual de cajas, palés y materiales implica riesgos ergonómicos, de aplastamiento y de corte, además de polvo y residuos químicos.\n\nLos EPI para esta fase combinan guantes antiimpacto y anticorte, calzado de seguridad, equipos de protección respiratoria y paños de limpieza rápida para mantener la eficiencia y la protección en un entorno dinámico.", "key_hazards": ["Esfuerzos ergonómicos por levantamiento", "Riesgos de aplastamiento", "Astillas y abrasiones", "Polvo y sílice", "Residuos químicos"], "ppe_solutions": ["Guantes ergonómicos antiimpacto", "Guantes de malla metálica y mangas resistentes a los cortes", "Calzado de seguridad con puntera y protección metatarsal", "Equipos de protección respiratoria P3/HEPA y gafas de seguridad", "Paños de limpieza rápida"]}]'::jsonb
  )
WHERE id = '88f125a1-b731-4da7-a59d-6da23446e550';

-- industry_solutions a3748cb9-5a3c-45d1-af3b-2f8a0d682a64
UPDATE industry_solutions
SET industry_name_locales = COALESCE(industry_name_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Steel Manufacturing"'::jsonb,
    'it', '"Produzione di Acciaio"'::jsonb,
    'fr', '"Production d''acier"'::jsonb,
    'de', '"Stahlproduktion"'::jsonb,
    'es', '"Producción de acero"'::jsonb
  ),
  description_locales = COALESCE(description_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Steel production involves diverse, high‐risk stages: raw material processing, smelting, casting, rolling, chemical treatments, and finishing. Risks include extreme temperatures, molten metal, sharp edges, chemical exposure, noise, mechanical hazards, and ergonomic strain. Effective safety requires stage‐specific PPE, strict protocols, and continuous monitoring."'::jsonb,
    'it', '"La produzione dell’acciaio comprende diverse fasi ad alto rischio: lavorazione delle materie prime, fusione, colata, laminazione, trattamenti chimici e finitura. I pericoli includono temperature estreme, metallo fuso, bordi taglienti, esposizione a sostanze chimiche, rumore, rischi meccanici e sforzi ergonomici. Una sicurezza efficace richiede DPI specifici per ogni fase, protocolli rigorosi e un monitoraggio continuo."'::jsonb,
    'fr', '"La production d''acier comprend plusieurs phases à haut risque : traitement des matières premières, fusion, coulée, laminage, traitements chimiques et finition. Les dangers incluent des températures extrêmes, du métal en fusion, des arêtes tranchantes, une exposition à des substances chimiques, du bruit, des risques mécaniques et des contraintes ergonomiques. Une sécurité efficace exige des EPI spécifiques à chaque phase, des protocoles rigoureux et une surveillance continue."'::jsonb,
    'de', '"Die Stahlproduktion umfasst mehrere Hochrisikophasen: Rohstoffaufbereitung, Schmelzen, Gießen, Walzen, chemische Behandlungen und Endbearbeitung. Zu den Gefahren zählen extreme Temperaturen, geschmolzenes Metall, scharfe Kanten, Chemikalienexposition, Lärm, mechanische Risiken und ergonomische Belastungen. Wirksame Sicherheit erfordert phasenspezifische PSA, strenge Protokolle und kontinuierliche Überwachung."'::jsonb,
    'es', '"La producción de acero comprende varias fases de alto riesgo: procesamiento de materias primas, fusión, colada, laminación, tratamientos químicos y acabado. Los peligros incluyen temperaturas extremas, metal fundido, bordes cortantes, exposición a sustancias químicas, ruido, riesgos mecánicos y esfuerzos ergonómicos. Una seguridad eficaz requiere EPI específicos para cada fase, protocolos rigurosos y una supervisión continua."'::jsonb
  ),
  features_locales = COALESCE(features_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '["Head-to-toe protection", "Extreme temperature protection", "350-800C contact heat protection"]'::jsonb,
    'it', '["Protezione da temperature estreme, fino a 1200C", "Articoli specifici per la protezione delle mani", "Protezione da testa a piedi"]'::jsonb,
    'fr', '["Protection contre les températures extrêmes, jusqu''à 1200C", "Articles spécifiques pour la protection des mains", "Protection de la tête aux pieds"]'::jsonb,
    'de', '["Schutz vor extremen Temperaturen bis zu 1200C", "Spezifische Artikel für den Handschutz", "Schutz von Kopf bis Fuß"]'::jsonb,
    'es', '["Protección frente a temperaturas extremas, hasta 1200C", "Artículos específicos para la protección de las manos", "Protección de la cabeza a los pies"]'::jsonb
  ),
  showcase_description_locales = COALESCE(showcase_description_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Steel manufacturing spans a range of intense and hazardous operations—from melting and shaping steel at thousands of degrees to handling heavy loads of scrap, chemical treatments, and logistics. With decades of expertise delivering robust safety and PPE solutions tailored to steel plants, we protect your workforce through every stage."'::jsonb,
    'it', '"La produzione dell’acciaio comprende una serie di operazioni intense e pericolose — dalla fusione e formatura dell’acciaio a temperature di migliaia di gradi, alla movimentazione di carichi pesanti di rottami, ai trattamenti chimici e alla logistica. Con decenni di esperienza nella fornitura di soluzioni di sicurezza e DPI robuste e specifiche per gli impianti siderurgici, proteggiamo la tua forza lavoro in ogni fase del processo."'::jsonb,
    'fr', '"La production d''acier comprend une série d''opérations intenses et dangereuses — de la fusion et du formage de l''acier à des températures de plusieurs milliers de degrés, à la manutention de charges lourdes de ferraille, en passant par les traitements chimiques et la logistique. Avec des décennies d''expérience dans la fourniture de solutions de sécurité et d''EPI robustes et spécifiques pour les aciéries, nous protégeons votre personnel à chaque étape du processus."'::jsonb,
    'de', '"Die Stahlproduktion umfasst eine Reihe intensiver und gefährlicher Vorgänge — vom Schmelzen und Formen von Stahl bei Temperaturen von mehreren tausend Grad über die Handhabung schwerer Schrottlasten bis hin zu chemischen Behandlungen und Logistik. Mit jahrzehntelanger Erfahrung in der Bereitstellung robuster, speziell für Stahlwerke entwickelter Sicherheitslösungen und PSA schützen wir Ihre Belegschaft in jeder Phase des Prozesses."'::jsonb,
    'es', '"La producción de acero comprende una serie de operaciones intensas y peligrosas — desde la fusión y el moldeado del acero a temperaturas de miles de grados, hasta la manipulación de cargas pesadas de chatarra, pasando por los tratamientos químicos y la logística. Con décadas de experiencia en el suministro de soluciones de seguridad y EPI robustos y específicos para las acerías, protegemos a su plantilla en cada fase del proceso."'::jsonb
  ),
  summary_content_locales = COALESCE(summary_content_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '"Steel production presents some of the most demanding safety challenges in industrial manufacturing. Workers are routinely exposed to extreme heat, molten metal splashes, high noise levels, sharp and heavy materials, and airborne contaminants such as metal fumes and dust. Each stage of the process — from furnace operations to rolling and finishing — introduces unique risks that can cause severe burns, cuts, respiratory issues, and impact injuries if not properly controlled. Effective protection therefore relies on specialized PPE designed for high heat, cut resistance, chemical handling, and respiratory safety, combined with strict adherence to safety procedures and continuous worker training to ensure long-term protection in these harsh environments."'::jsonb,
    'it', '"La produzione dell’acciaio presenta alcune delle sfide di sicurezza più impegnative nell’ambito industriale. Gli operatori sono regolarmente esposti a calore estremo, schizzi di metallo fuso, livelli elevati di rumore, materiali taglienti e pesanti, oltre a contaminanti aerodispersi come fumi e polveri metalliche. Ogni fase del processo — dalla fusione alla laminazione e finitura — comporta rischi specifici che possono causare ustioni gravi, tagli, problemi respiratori e traumi da impatto se non adeguatamente controllati. Una protezione efficace richiede quindi DPI specializzati per la resistenza al calore, al taglio, alle sostanze chimiche e per la sicurezza respiratoria, insieme a rigorose procedure di sicurezza e a una formazione continua dei lavoratori per garantire una protezione duratura in ambienti tanto difficili."'::jsonb,
    'fr', '"La production de l''acier présente certains des défis de sécurité les plus exigeants du secteur industriel. Les opérateurs sont régulièrement exposés à une chaleur extrême, à des projections de métal en fusion, à des niveaux de bruit élevés, à des matériaux coupants et lourds, ainsi qu''à des contaminants en suspension dans l''air tels que fumées et poussières métalliques. Chaque étape du processus — de la fusion au laminage et à la finition — comporte des risques spécifiques pouvant provoquer des brûlures graves, des coupures, des problèmes respiratoires et des traumatismes par impact si elle n''est pas correctement maîtrisée. Une protection efficace nécessite donc des EPI spécialisés pour la résistance à la chaleur, à la coupure, aux produits chimiques et pour la protection respiratoire, associés à des procédures de sécurité rigoureuses et à une formation continue des travailleurs afin de garantir une protection durable dans des environnements aussi difficiles."'::jsonb,
    'de', '"Die Stahlproduktion stellt einige der anspruchsvollsten Sicherheitsherausforderungen im industriellen Bereich dar. Die Beschäftigten sind regelmäßig extremer Hitze, Spritzern von geschmolzenem Metall, hohen Lärmpegeln, scharfkantigen und schweren Materialien sowie luftgetragenen Schadstoffen wie Rauch und Metallstäuben ausgesetzt. Jede Phase des Prozesses — vom Schmelzen über das Walzen bis zur Endbearbeitung — birgt spezifische Risiken, die bei unzureichender Kontrolle schwere Verbrennungen, Schnittverletzungen, Atemwegsprobleme und Stoßtraumata verursachen können. Ein wirksamer Schutz erfordert daher spezialisierte PSA für Hitzebeständigkeit, Schnittfestigkeit, Chemikalienbeständigkeit und Atemschutz, zusammen mit strengen Sicherheitsverfahren und einer kontinuierlichen Schulung der Arbeitnehmer, um einen dauerhaften Schutz in derart anspruchsvollen Umgebungen zu gewährleisten."'::jsonb,
    'es', '"La producción de acero presenta algunos de los desafíos de seguridad más exigentes del ámbito industrial. Los operarios están expuestos regularmente a calor extremo, salpicaduras de metal fundido, niveles elevados de ruido, materiales cortantes y pesados, además de contaminantes transportados por el aire como humos y polvos metálicos. Cada fase del proceso —desde la fusión hasta el laminado y el acabado— conlleva riesgos específicos que pueden causar quemaduras graves, cortes, problemas respiratorios y traumatismos por impacto si no se controlan adecuadamente. Una protección eficaz requiere, por tanto, EPI especializados para la resistencia al calor, al corte, a las sustancias químicas y para la protección respiratoria, junto con procedimientos de seguridad rigurosos y una formación continua de los trabajadores para garantizar una protección duradera en entornos tan exigentes."'::jsonb
  ),
  sections_locales = COALESCE(sections_locales, '{}'::jsonb) || jsonb_build_object(
    'en', '[{"title": "Raw Material Handling & Preparation", "description": "The steelmaking process begins with handling raw materials such as iron ore, coal, limestone, and scrap metal. These materials are transported, crushed, stored, and prepared for charging into the furnace. Workers in this stage are exposed to significant physical and environmental risks due to heavy equipment, dust, and noise.", "key_hazards": ["Dust and airborne particles (silica, metal dust)", "Noise from crushers and conveyors", "Manual handling and heavy loads on slippery surface", "Abrasive and sharp materials"], "ppe_solutions": ["Respiratory protection (P2/P3 masks or half masks with filters)", "Hearing protection (earplugs or earmuffs, EN 352)", "Safety footwear with toe protection, back support belts, gloves with grip", "Cut- and abrasion-resistant gloves (EN 388), protective clothing"]}, {"title": "Melting and Furnace Operations", "description": "At this stage, raw materials are transformed into molten steel in blast furnaces or electric arc furnaces. Temperatures exceed 1,500°C, creating an environment of intense heat, molten metal splashes, and harmful fumes. It’s one of the most hazardous phases of steel production.", "key_hazards": ["Extreme radiant heat and thermal burns", "Molten metal splashes and slag projection", "Metal fumes and gases (CO, SO₂, FeO)", "Hot and slippery surfaces"], "ppe_solutions": ["Aluminized heat-resistant clothing, gloves, and face shields (EN 407)", "Flame-retardant, spatter-resistant PPE, heat-reflective visors", "Respiratory protection (PAPR or half masks with high-temp filters)", "Heat-resistant, anti-slip safety boots with metatarsal guards"]}, {"title": "Casting and Forming", "description": "Molten steel is cast into slabs, billets, or blooms, then rolled or forged into the required shape. This phase involves powerful machinery and moving metal, exposing workers to crush injuries, hot surfaces, and sharp edges.", "key_hazards": ["Contact with hot metal and surfaces", "Sharp edges of semi-finished steel", "Noise and vibration", "Flying scale, sparks, and particles"], "ppe_solutions": ["Heat-resistant gloves and sleeves, long-sleeved protective clothing", "Cut-resistant gloves (EN 388, level D–F), forearm protection", "Anti-vibration gloves, hearing protection", "Face shield or safety goggles (EN 166, molten metal rated)"]}, {"title": "Surface Treatment and Finishing", "description": "After forming, steel may undergo processes such as pickling, galvanizing, coating, and painting. These operations introduce chemical, thermal, and mechanical hazards that demand careful PPE selection.", "key_hazards": ["Chemical exposure (acids, alkalis, solvents)", "Fumes from coatings and solvents", "Thermal burns from hot baths or parts", "Sharp edges during trimming and inspection"], "ppe_solutions": ["Chemical-resistant gloves (EN 374), PVC or neoprene suits", "Respirators with organic vapour filters", "Heat-resistant gloves, long-sleeved flame-retardant clothing", "Cut-resistant gloves and forearm protection"]}, {"title": "Maintenance and Repair", "description": "Maintenance covers routine checks, mechanical and electrical repairs, cleaning, and shutdown operations. These tasks often involve confined spaces, welding, and work at height — all of which present critical hazards.", "key_hazards": ["Electrical shock and arc flash", "Welding arcs and hot sparks", "Noise and dust during grinding"], "ppe_solutions": ["Arc-rated protective clothing, dielectric gloves", "Welding helmets (auto-darkening), flame-resistant gloves, jackets", "Hearing protection and respirators"]}, {"title": "Logistics and Scrap Handling", "description": "The final stage involves moving, loading, and recycling steel products and scrap. Workers handle sharp and heavy materials, operate forklifts, and work around moving vehicles — making impact and cut protection vital.", "key_hazards": ["Cuts from sharp scrap or sheet metal", "Impact injuries from dropped materials", "Dust and metal particles", "Poor visibility in traffic zones"], "ppe_solutions": ["High cut-resistant gloves (EN 388, F level), arm guards", "Safety shoes with toe and metatarsal protection", "Respiratory masks or half masks with particulate filters", "High-visibility clothing (EN ISO 20471)"]}]'::jsonb,
    'it', '[{"title": "Movimentazione e Preparazione delle Materie Prime", "description": "Il processo siderurgico inizia con la gestione delle materie prime come minerale di ferro, carbone, calcare e rottami metallici. Questi materiali vengono trasportati, frantumati, stoccati e preparati per essere caricati nel forno. Gli operatori sono esposti a rischi fisici e ambientali significativi dovuti all’uso di macchinari pesanti, alla presenza di polveri e al rumore. ", "key_hazards": ["Polveri e particelle aerodisperse (silice, polveri metalliche)", "Rumore da frantoi e nastri trasportatori", "Movimentazione manuale e carichi pesanti su superfici scivolose", "Materiali abrasivi o taglienti"], "ppe_solutions": ["Protezione respiratoria (maschere P2/P3 o semimaschere con filtri)", "Protezione acustica (tappi o cuffie antirumore, EN 352)", "Calzature di sicurezza con puntale, cinture lombari, guanti con grip", "Guanti resistenti al taglio e all’abrasione (EN 388), indumenti protettivi"]}, {"title": "Fusione e Operazioni al Forno", "description": "In questa fase, le materie prime vengono trasformate in acciaio fuso all’interno di altiforni o forni elettrici ad arco. Le temperature superano i 1.500°C, generando un ambiente di calore estremo, schizzi di metallo fuso e fumi nocivi. È una delle fasi più pericolose dell’intero processo produttivo.", "key_hazards": ["Calore radiante estremo e ustioni termiche", "Schizzi di metallo fuso e proiezioni di scorie", "Fumi e gas metallici (CO, SO₂, FeO)", "Superfici calde e scivolose"], "ppe_solutions": ["Indumenti, guanti e visiere resistenti al calore (EN 407), rivestiti in alluminio", "Indumenti ignifughi e resistenti agli schizzi, visiere riflettenti", "Protezione respiratoria (PAPR o semimaschere con filtri ad alta temperatura)", "Scarpe di sicurezza resistenti al calore con protezione metatarsale e suola antiscivolo"]}, {"title": "Colata e Formatura", "description": "L’acciaio fuso viene colato in lingotti, billette o bramme, per poi essere laminato o forgiato nella forma desiderata. Questa fase coinvolge macchinari potenti e materiali incandescenti, esponendo gli operatori a rischi di schiacciamento, ustioni e tagli.", "key_hazards": ["Contatto con metallo o superfici calde", "Punti di schiacciamento nei laminatoi", "Bordi taglienti dei semilavorati", "Scaglie, scintille e particelle volanti"], "ppe_solutions": ["Guanti e maniche resistenti al calore, indumenti a maniche lunghe", "Guanti antiurto e calzature di sicurezza rinforzate", "Guanti antitaglio (EN 388, livello D–F), protezioni per l’avambraccio", "Visiera o occhiali di sicurezza (EN 166, specifici per metallo fuso)"]}, {"title": "Trattamento Superficiale e Finitura", "description": "Dopo la formatura, l’acciaio può essere sottoposto a processi di decapaggio, zincatura, rivestimento o verniciatura. Queste operazioni comportano rischi chimici, termici e meccanici che richiedono DPI adeguati e ben selezionati.", "key_hazards": ["Esposizione a sostanze chimiche (acidi, basi, solventi)", "Fumi di vernici o rivestimenti", "Ustioni da bagni caldi o superfici roventi", "Tagli durante rifinitura o ispezione"], "ppe_solutions": ["Guanti resistenti agli agenti chimici (EN 374), tute in PVC o neoprene", "Respiratori con filtri per vapori organici", "Guanti resistenti al calore, indumenti ignifughi a maniche lunghe", "Guanti e protezioni per avambracci antitaglio"]}, {"title": "Manutenzione e Riparazione", "description": "Le attività di manutenzione comprendono controlli periodici, riparazioni meccaniche ed elettriche, pulizia e fermate impiantistiche. Queste operazioni comportano spesso lavori in spazi confinati, saldature e interventi in quota, con rischi elevati per la sicurezza.", "key_hazards": ["Scosse elettriche e arco elettrico", "Arco di saldatura e proiezioni di scintille", "Rumore e polveri da molatura"], "ppe_solutions": ["Indumenti protettivi certificati per arco elettrico, guanti dielettrici", "Caschi da saldatore automatici, guanti e giacche ignifughe", "Cuffie antirumore e protezioni respiratorie"]}, {"title": "Logistica e Gestione dei Rottami", "description": "L’ultima fase comprende la movimentazione, il carico e il riciclo di prodotti e rottami di acciaio. Gli operatori manipolano materiali pesanti e taglienti, utilizzano carrelli elevatori e lavorano in prossimità di mezzi in movimento, rendendo essenziali la protezione da urti e tagli.", "key_hazards": ["Tagli da lamiere o rottami metallici", "Urti da caduta di materiali", "Polveri e particelle metalliche", "Rumore da mezzi e macchinari", "Scarsa visibilità nelle aree di traffico"], "ppe_solutions": ["Guanti ad alta resistenza al taglio (EN 388, livello F), protezioni per il braccio", "Calzature di sicurezza con puntale e protezione metatarsale", "Maschere filtranti o semimaschere con filtri antiparticolato", "Cuffie antirumore (EN 352)", "Indumenti ad alta visibilità (EN ISO 20471)"]}]'::jsonb,
    'fr', '[{"title": "Manutention et préparation des matières premières", "description": "Le processus sidérurgique commence par la gestion des matières premières telles que le minerai de fer, le charbon, le calcaire et la ferraille. Ces matériaux sont transportés, concassés, stockés et préparés pour être chargés dans le four. Les opérateurs sont exposés à des risques physiques et environnementaux importants dus à l''utilisation de machines lourdes, à la présence de poussières et au bruit. ", "key_hazards": ["Poussières et particules en suspension dans l''air (silice, poussières métalliques)", "Bruit des concasseurs et des convoyeurs", "Manutention manuelle et charges lourdes sur surfaces glissantes", "Matériaux abrasifs ou tranchants"], "ppe_solutions": ["Protection respiratoire (masques P2/P3 ou demi-masques avec filtres)", "Protection auditive (bouchons ou casques antibruit, EN 352)", "Chaussures de sécurité à embout, ceintures lombaires, gants antidérapants", "Gants résistants à la coupure et à l''abrasion (EN 388), vêtements de protection"]}, {"title": "Fusion et opérations au four", "description": "À cette étape, les matières premières sont transformées en acier fondu dans des hauts fourneaux ou des fours électriques à arc. Les températures dépassent 1 500 °C, créant un environnement de chaleur extrême, des projections de métal en fusion et des fumées nocives. C''est l''une des étapes les plus dangereuses de l''ensemble du processus de production.", "key_hazards": ["Chaleur radiante extrême et brûlures thermiques", "Projections de métal en fusion et de scories", "Fumées et gaz métalliques (CO, SO₂, FeO)", "Surfaces chaudes et glissantes"], "ppe_solutions": ["Vêtements, gants et visières résistants à la chaleur (EN 407), revêtus d''aluminium", "Vêtements ignifuges et résistants aux projections, visières réfléchissantes", "Protection respiratoire (PAPR ou demi-masques avec filtres haute température)", "Chaussures de sécurité résistantes à la chaleur avec protection métatarsienne et semelle antidérapante"]}, {"title": "Coulée et formage", "description": "L''acier fondu est coulé en lingots, billettes ou brames, avant d''être laminé ou forgé dans la forme souhaitée. Cette phase implique des machines puissantes et des matériaux incandescents, exposant les opérateurs à des risques d''écrasement, de brûlures et de coupures.", "key_hazards": ["Contact avec du métal ou des surfaces chaudes", "Points d''écrasement dans les laminoirs", "Arêtes tranchantes des produits semi-finis", "Écailles, étincelles et particules volantes"], "ppe_solutions": ["Gants et manchettes résistants à la chaleur, vêtements à manches longues", "Gants anti-chocs et chaussures de sécurité renforcées", "Gants anticoupure (EN 388, niveau D–F), protections pour l''avant-bras", "Visière ou lunettes de sécurité (EN 166, spécifiques pour le métal en fusion)"]}, {"title": "Traitement de surface et finition", "description": "Après le formage, l''acier peut être soumis à des procédés de décapage, de galvanisation, de revêtement ou de peinture. Ces opérations comportent des risques chimiques, thermiques et mécaniques nécessitant des EPI adaptés et soigneusement sélectionnés.", "key_hazards": ["Exposition à des substances chimiques (acides, bases, solvants)", "Vapeurs de peintures ou de revêtements", "Brûlures dues aux bains chauds ou aux surfaces incandescentes", "Coupures pendant la finition ou l''inspection"], "ppe_solutions": ["Gants résistants aux agents chimiques (EN 374), combinaisons en PVC ou néoprène", "Appareils respiratoires avec filtres pour vapeurs organiques", "Gants résistants à la chaleur, vêtements ignifuges à manches longues", "Gants et protections d''avant-bras anticoupure"]}, {"title": "Maintenance et réparation", "description": "Les activités de maintenance comprennent des contrôles périodiques, des réparations mécaniques et électriques, le nettoyage et les arrêts d''installation. Ces opérations impliquent souvent des travaux en espaces confinés, des soudages et des interventions en hauteur, avec des risques élevés pour la sécurité.", "key_hazards": ["Chocs électriques et arc électrique", "Arc de soudage et projections d''étincelles", "Bruit et poussières de meulage"], "ppe_solutions": ["Vêtements de protection certifiés contre l''arc électrique, gants diélectriques", "Casques de soudeur automatiques, gants et vestes ignifuges", "Casques antibruit et protections respiratoires"]}, {"title": "Logistique et Gestion des Ferrailles", "description": "La dernière phase comprend la manutention, le chargement et le recyclage des produits et des ferrailles d''acier. Les opérateurs manipulent des matériaux lourds et tranchants, utilisent des chariots élévateurs et travaillent à proximité de véhicules en mouvement, rendant essentielle la protection contre les chocs et les coupures.", "key_hazards": ["Coupures dues aux tôles ou aux ferrailles métalliques", "Chocs dus à la chute de matériaux", "Poussières et particules métalliques", "Bruit des véhicules et des machines", "Faible visibilité dans les zones de circulation"], "ppe_solutions": ["Gants à haute résistance à la coupure (EN 388, niveau F), protections pour le bras", "Chaussures de sécurité avec embout et protection métatarsienne", "Masques filtrants ou demi-masques avec filtres antiparticules", "Casques antibruit (EN 352)", "Vêtements à haute visibilité (EN ISO 20471)"]}]'::jsonb,
    'de', '[{"title": "Handhabung und Aufbereitung der Rohstoffe", "description": "Der Stahlherstellungsprozess beginnt mit der Handhabung von Rohstoffen wie Eisenerz, Kohle, Kalkstein und Metallschrott. Diese Materialien werden transportiert, zerkleinert, gelagert und für die Beschickung des Ofens vorbereitet. Die Bediener sind aufgrund des Einsatzes schwerer Maschinen, der Staubbelastung und des Lärms erheblichen physischen und umweltbedingten Risiken ausgesetzt. ", "key_hazards": ["Staub und luftgetragene Partikel (Kieselsäure, Metallstäube)", "Lärm durch Brecher und Förderbänder", "Manuelle Handhabung und schwere Lasten auf rutschigen Oberflächen", "Abrasive oder scharfkantige Materialien"], "ppe_solutions": ["Atemschutz (P2/P3-Masken oder Halbmasken mit Filtern)", "Gehörschutz (Gehörschutzstöpsel oder Kapselgehörschutz, EN 352)", "Sicherheitsschuhe mit Zehenschutzkappe, Rückenstützgürtel, griffige Handschuhe", "Schnitt- und abriebfeste Handschuhe (EN 388), Schutzkleidung"]}, {"title": "Schmelzen und Ofenbetrieb", "description": "In dieser Phase werden die Rohstoffe in Hochöfen oder Elektrolichtbogenöfen zu geschmolzenem Stahl verarbeitet. Die Temperaturen übersteigen 1.500 °C und erzeugen eine Umgebung mit extremer Hitze, Spritzern von geschmolzenem Metall und schädlichen Dämpfen. Dies ist eine der gefährlichsten Phasen des gesamten Produktionsprozesses.", "key_hazards": ["Extreme Strahlungswärme und thermische Verbrennungen", "Spritzer von geschmolzenem Metall und Schlackeauswurf", "Metalldämpfe und -gase (CO, SO₂, FeO)", "Heiße und rutschige Oberflächen"], "ppe_solutions": ["Hitzebeständige Kleidung, Handschuhe und Visiere (EN 407), aluminiumbeschichtet", "Feuerfeste und spritzbeständige Kleidung, reflektierende Visiere", "Atemschutz (PAPR oder Halbmasken mit Hochtemperaturfiltern)", "Hitzebeständige Sicherheitsschuhe mit Mittelfußschutz und rutschfester Sohle"]}, {"title": "Gießen und Formgebung", "description": "Der geschmolzene Stahl wird zu Blöcken, Knüppeln oder Brammen gegossen und anschließend gewalzt oder in die gewünschte Form geschmiedet. Diese Phase erfordert leistungsstarke Maschinen und glühend heiße Materialien und setzt die Bediener Quetsch-, Verbrennungs- und Schnittgefahren aus.", "key_hazards": ["Kontakt mit heißem Metall oder heißen Oberflächen", "Quetschstellen in den Walzwerken", "Scharfe Kanten der Halbzeuge", "Zunder, Funken und umherfliegende Partikel"], "ppe_solutions": ["Hitzebeständige Handschuhe und Ärmel, langärmelige Kleidung", "Stoßschutzhandschuhe und verstärkte Sicherheitsschuhe", "Schnittschutzhandschuhe (EN 388, Stufe D–F), Unterarmschutz", "Visier oder Schutzbrille (EN 166, speziell für geschmolzenes Metall)"]}, {"title": "Oberflächenbehandlung und Endbearbeitung", "description": "Nach der Formgebung kann der Stahl Beiz-, Verzinkungs-, Beschichtungs- oder Lackierprozessen unterzogen werden. Diese Vorgänge bergen chemische, thermische und mechanische Risiken, die geeignete und sorgfältig ausgewählte PSA erfordern.", "key_hazards": ["Exposition gegenüber Chemikalien (Säuren, Laugen, Lösungsmittel)", "Dämpfe von Farben oder Beschichtungen", "Verbrennungen durch heiße Bäder oder glühende Oberflächen", "Schnittverletzungen bei der Endbearbeitung oder Prüfung"], "ppe_solutions": ["Chemikalienbeständige Handschuhe (EN 374), Overalls aus PVC oder Neopren", "Atemschutzgeräte mit Filtern für organische Dämpfe", "Hitzebeständige Handschuhe, feuerfeste langärmelige Kleidung", "Schnittschutzhandschuhe und Unterarmschutz"]}, {"title": "Wartung und Reparatur", "description": "Die Wartungsarbeiten umfassen regelmäßige Kontrollen, mechanische und elektrische Reparaturen, Reinigung und Anlagenstillstände. Diese Arbeiten beinhalten häufig Arbeiten in engen Räumen, Schweißarbeiten und Höhenarbeiten mit hohen Sicherheitsrisiken.", "key_hazards": ["Stromschläge und Lichtbogen", "Schweißlichtbogen und Funkenflug", "Lärm und Schleifstaub"], "ppe_solutions": ["Zertifizierte Schutzkleidung gegen Lichtbogen, dielektrische Handschuhe", "Automatische Schweißerhelme, feuerfeste Handschuhe und Jacken", "Gehörschutzkapseln und Atemschutz"]}, {"title": "Logistik und Schrottmanagement", "description": "Die letzte Phase umfasst die Handhabung, das Verladen und das Recycling von Stahlprodukten und -schrott. Die Bediener handhaben schwere und scharfe Materialien, benutzen Gabelstapler und arbeiten in der Nähe von sich bewegenden Fahrzeugen, wodurch Stoß- und Schnittschutz unerlässlich sind.", "key_hazards": ["Schnittverletzungen durch Bleche oder Metallschrott", "Stöße durch herabfallende Materialien", "Staub und Metallpartikel", "Lärm durch Fahrzeuge und Maschinen", "Schlechte Sichtbarkeit in Verkehrsbereichen"], "ppe_solutions": ["Handschuhe mit hoher Schnittfestigkeit (EN 388, Stufe F), Armschutz", "Sicherheitsschuhe mit Zehenschutzkappe und Metatarsalschutz", "Filtermasken oder Halbmasken mit Partikelfiltern", "Gehörschutzkapseln (EN 352)", "Warnkleidung mit hoher Sichtbarkeit (EN ISO 20471)"]}]'::jsonb,
    'es', '[{"title": "Manipulación y preparación de las materias primas", "description": "El proceso siderúrgico comienza con la gestión de materias primas como mineral de hierro, carbón, caliza y chatarra metálica. Estos materiales se transportan, trituran, almacenan y preparan para su carga en el horno. Los operarios están expuestos a riesgos físicos y ambientales significativos debido al uso de maquinaria pesada, la presencia de polvo y el ruido. ", "key_hazards": ["Polvo y partículas en suspensión en el aire (sílice, polvo metálico)", "Ruido de trituradoras y cintas transportadoras", "Manipulación manual y cargas pesadas sobre superficies resbaladizas", "Materiales abrasivos o cortantes"], "ppe_solutions": ["Protección respiratoria (mascarillas P2/P3 o semimáscaras con filtros)", "Protección auditiva (tapones o auriculares antirruido, EN 352)", "Calzado de seguridad con puntera, fajas lumbares, guantes con agarre", "Guantes resistentes al corte y a la abrasión (EN 388), ropa de protección"]}, {"title": "Fusión y operaciones en el horno", "description": "En esta fase, las materias primas se transforman en acero fundido dentro de altos hornos o hornos eléctricos de arco. Las temperaturas superan los 1.500 °C, generando un entorno de calor extremo, salpicaduras de metal fundido y humos nocivos. Es una de las fases más peligrosas de todo el proceso productivo.", "key_hazards": ["Calor radiante extremo y quemaduras térmicas", "Salpicaduras de metal fundido y proyecciones de escoria", "Humos y gases metálicos (CO, SO₂, FeO)", "Superficies calientes y resbaladizas"], "ppe_solutions": ["Ropa, guantes y viseras resistentes al calor (EN 407), recubiertos de aluminio", "Ropa ignífuga y resistente a las salpicaduras, viseras reflectantes", "Protección respiratoria (PAPR o semimáscaras con filtros de alta temperatura)", "Calzado de seguridad resistente al calor con protección metatarsal y suela antideslizante"]}, {"title": "Colada y moldeado", "description": "El acero fundido se cuela en lingotes, tochos o planchones, para luego ser laminado o forjado en la forma deseada. Esta fase implica maquinaria potente y materiales incandescentes, exponiendo a los operarios a riesgos de aplastamiento, quemaduras y cortes.", "key_hazards": ["Contacto con metal o superficies calientes", "Puntos de aplastamiento en los laminadores", "Bordes cortantes de los semielaborados", "Cascarillas, chispas y partículas volantes"], "ppe_solutions": ["Guantes y mangas resistentes al calor, ropa de manga larga", "Guantes antiimpacto y calzado de seguridad reforzado", "Guantes anticorte (EN 388, nivel D–F), protecciones para el antebrazo", "Visera o gafas de seguridad (EN 166, específicas para metal fundido)"]}, {"title": "Tratamiento superficial y acabado", "description": "Después del moldeado, el acero puede someterse a procesos de decapado, galvanizado, revestimiento o pintado. Estas operaciones conllevan riesgos químicos, térmicos y mecánicos que requieren EPI adecuados y bien seleccionados.", "key_hazards": ["Exposición a sustancias químicas (ácidos, bases, disolventes)", "Vapores de pinturas o revestimientos", "Quemaduras por baños calientes o superficies al rojo vivo", "Cortes durante el acabado o la inspección"], "ppe_solutions": ["Guantes resistentes a agentes químicos (EN 374), monos de PVC o neopreno", "Equipos de protección respiratoria con filtros para vapores orgánicos", "Guantes resistentes al calor, ropa ignífuga de manga larga", "Guantes y protecciones para antebrazos anticorte"]}, {"title": "Mantenimiento y reparación", "description": "Las actividades de mantenimiento incluyen controles periódicos, reparaciones mecánicas y eléctricas, limpieza y paradas de planta. Estas operaciones implican a menudo trabajos en espacios confinados, soldaduras e intervenciones en altura, con riesgos elevados para la seguridad.", "key_hazards": ["Descargas eléctricas y arco eléctrico", "Arco de soldadura y proyecciones de chispas", "Ruido y polvo de amolado"], "ppe_solutions": ["Ropa de protección certificada contra el arco eléctrico, guantes dieléctricos", "Cascos de soldador automáticos, guantes y chaquetas ignífugas", "Orejeras antirruido y protecciones respiratorias"]}, {"title": "Logística y Gestión de Chatarra", "description": "La última fase incluye la manipulación, la carga y el reciclaje de productos y chatarra de acero. Los operarios manipulan materiales pesados y cortantes, utilizan carretillas elevadoras y trabajan cerca de vehículos en movimiento, lo que hace esencial la protección contra golpes y cortes.", "key_hazards": ["Cortes por chapas o chatarra metálica", "Golpes por caída de materiales", "Polvo y partículas metálicas", "Ruido de vehículos y maquinaria", "Escasa visibilidad en las zonas de tráfico"], "ppe_solutions": ["Guantes de alta resistencia al corte (EN 388, nivel F), protecciones para el brazo", "Calzado de seguridad con puntera y protección metatarsal", "Mascarillas filtrantes o semimáscaras con filtros antipartículas", "Orejeras antirruido (EN 352)", "Ropa de alta visibilidad (EN ISO 20471)"]}]'::jsonb
  )
